(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["video"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-chunk-overlap-long-video"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-1\">一 · 事故现场：当“切块”把长视频切成碎片</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-2\">二 · 它解决什么：把显存约束与运动连续性拆开处理</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-3\">三 · 它不解决什么：四条明确的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-4\">四 · 融合公式与它的工程含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-5\">五 · 吞吐折减与批大小的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-6\">六 · 适用边界的工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-7\">七 · 边界不在时长，而在“重叠预算”与“KV 记忆”两条硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-8\">八 · 切块与锚点登记：请求进入时的第一次显存裁决</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-9\">九 · 条件采样：重叠帧 KV 与 latent 如何进入单块计算图</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-10\">十 · 新帧解码与流式输出：把 VAE 从关键路径上摘出来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-11\">十一 · 重叠区加权融合与运动一致性检查</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-12\">十二 · 跨块 KV 池的写入、读取与淘汰</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-13\">十三 · 步骤间的依赖与流水排布</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-14\">十四 · 边界条件、失效路径与每步的系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-15\">十五 · 融合公式的逐项解剖与衰减核的由来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-16\">十六 · 首块时延的分解与流式节奏的瓶颈项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-17\">十七 · 显存上界的构成与 KV 池容量对总时长的硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-18\">十八 · 吞吐折减的推导与批大小的折减配方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-19\">十九 · 运动一致性检查的判据与不可修复性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-20\">二十 · 与相邻算法的公式级分野</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-21\">二十一 · 请求形态的匹配面：长时长、定分辨率、定步数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-22\">二十二 · 长度分布：短请求是毒药，长尾才是主菜</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-23\">二十三 · 并发与批大小的折减公式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-24\">二十四 · 负载不对时的三种崩法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-25\">二十五 · 配方表与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-26\">二十六 · 负载配方：什么请求吃得住这套编排，什么请求会把它拖垮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-27\">二十七 · 硬件档位：按单块窗口驻留反推，而不是按时长买卡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-28\">二十八 · 并行拓扑：块内并行与块间串行的边界要画清楚</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-29\">二十九 · 量化方案：分层给精度，别把融合区当普通激活</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-30\">三十 · KV 策略：池容量上限就是可支持总时长的硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-31\">三十一 · 调度参数：重叠比例、批大小与流式节奏的三角约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-32\">三十二 · 显存账本：单块窗口、KV 池与 VAE 工作区的三份预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-33\">三十三 · 带宽：重叠帧的重复搬运比重复计算更贵</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-34\">三十四 · 通信：跨块锚定在单节点内是 NVLink 域内的事</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-35\">三十五 · 功耗与热：流式节奏下的占空比问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-36\">三十六 · 尾延迟：最慢块决定流式节奏</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-37\">三十七 · 规模上去以后先崩的顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-38\">三十八 · 规模上去以后，先崩的是 KV 池而不是单块窗口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-39\">三十九 · 精度问题：融合区的数值塌陷与量化误差放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-40\">四十 · OOM：显存预算的三项分解与淘汰策略的误伤</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-41\">四十一 · 批抖动与路由不均：批大小受窗口约束后的调度失衡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-42\">四十二 · 尾延迟尖刺：流式节奏被最慢块拖住</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-43\">四十三 · 监控指标与回滚路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-44\">四十四 · 诊断顺序与工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-45\">四十五 · 失效边界：从接缝漏检到 KV 误淘汰的连锁反应</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-46\">四十六 · 对照轴：显存换法、连续性来源、延迟结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-47\">四十七 · 决策表：四类候选与适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-48\">四十八 · 选型判据：用公式把条件写成不等式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-49\">四十九 · 与量化、稀疏、缓存的组合次序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-50\">五十 · 失败模式对应的选型纠偏</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-51\">五十一 · 选型的工程落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunk-overlap-long-video-sec-52\">五十二 · 选型边界：重叠分块、自回归滚动与序列并行怎么分工</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:520px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 520.5 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"438.5\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按固定帧数切块，相邻块保留若干重叠帧作为上下文锚点。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"438.5\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">每块以重叠帧的KV cache与latent为条件做扩散/流匹配采样。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"438.5\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">块生成后仅对非重叠新帧做VAE解码并流式输出，重叠帧缓存待融合。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"438.5\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">相邻块重叠区按时间距离加权融合latent，再做运动一致性检查。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"438.5\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">维护跨块KV池，超长时按重要性淘汰旧块KV控制显存。</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-chunk-overlap-long-video-sec-1\">一 · 事故现场：当“切块”把长视频切成碎片</h3>\n<p>设想一条已经上线的短视频生成服务：用户提交一段 60 秒、固定分辨率、固定采样步数的生成请求，期望在提交后几秒内看到首帧开始播放，之后画面持续流出。工程团队最初的做法很朴素——把总帧数按单次 DiT 时空注意力窗口能容纳的上限等长切块，逐块串行采样、逐块 VAE 解码、逐块推给播放端。上线首日，监控面板上出现两类告警同时爆发：一类是首帧时延尚可、但块与块之间的帧间隔出现明显尖峰，播放端表现为规律性的“一顿一顿”；另一类是用户投诉画面在固定时间点出现横向撕裂状的接缝，人物手臂在块边界处凭空多出一截，运动方向在边界帧前后发生跳变。</p>\n<p>排查结论并不复杂：等长切块让每一块都从“无上下文”的初始状态开始采样，块边界两侧的 latent 各自独立收敛，缺少共同的运动锚点；同时块间没有任何重叠，VAE 解码在边界帧上也没有可融合的冗余信息。更麻烦的是流式输出的节奏问题——每一块都必须完整走完采样与 VAE 解码才能吐出第一帧新画面，块内计算量与块间调度开销叠加，最慢的那一块直接决定了整条流的节奏。这不是模型能力问题，而是推理组织方式问题：单块显存被限制住了，跨块的运动连续性却被丢掉了。</p>\n<p>这个事故精确划定了本算法要解决的推理问题边界：长视频总帧数超出单次 DiT 的时空注意力窗口与显存上限，朴素切块在块边界产生接缝与运动断裂，而流式输出又要求块间低延迟衔接。三者同时成立时，才需要“分块 + 重叠 + 锚定 + 融合”这一整套编排；缺任何一条，都有更简单的方案可用。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-2\">二 · 它解决什么：把显存约束与运动连续性拆开处理</h3>\n<p>核心判断是：显存上限由单块窗口决定，而运动连续性由跨块条件决定，两者不必绑在同一个计算图里。算法按固定帧数切块，相邻块保留若干重叠帧作为上下文锚点；每块以重叠帧的 KV cache 与 latent 为条件做扩散/流匹配采样。也就是说，块内仍然保留完整的双向时空注意力，不改变单次注意力的计算图，只是把“上一块已经确定的运动状态”作为条件注入当前块。这一点与逐帧因果生成的自回归路线形成分工：后者靠因果掩码维持连续性，前者靠重叠帧的 KV/latent 锚定维持连续性，块内双向注意力带来的画面质量不被牺牲。</p>\n<p>显存账可以写得很直白：单块驻留的 latent 加上跨块 KV 池加上 VAE 解码工作区，构成显存预算。若记单块帧数为 $N_{\\text{chunk}}$、重叠帧数为 $N_{\\text{overlap}}$，则</p>\n<div class=\"formula\">$$\\text{mem}\\propto N_{\\text{overlap}},\\qquad \\text{latency}_{\\text{first chunk}}\\approx T_{\\text{chunk}}+T_{\\text{VAE}}$$</div>\n<p>第一式说明重叠帧是显存的直接放大器，第二式说明首帧时延由首块采样时间与首块 VAE 解码时间共同决定——重叠帧越多，首块计算越重，首帧越晚。这就是为什么重叠比例不能凭感觉调：它是显存、首帧时延与吞吐三者之间的同一个旋钮。</p>\n<p>具体例子：一条 60 秒、固定分辨率的请求，单次注意力窗口只能容纳远小于总帧数的帧数，按固定帧数切成若干块，相邻块保留若干重叠帧。若不加重叠，块边界处两块各自从零状态采样，接缝几乎必然出现；加了重叠锚定后，当前块在重叠区已经“看到”上一块的运动趋势，边界帧由两块共同约束，接缝被显著压低。代价是重叠帧被重复计算，重叠比例越高，单块计算量越大，吞吐越低。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-3\">三 · 它不解决什么：四条明确的失效边界</h3>\n<p>第一条，它不解决单块窗口内部的显存问题。如果单块 latent 加 VAE 工作区本身就放不下，切块再细也没用，此时需要的是量化（FP8/NVFP4 降低单块激活与 KV 占用）或更细的窗口切分，而不是重叠编排。第二条，它不解决远距离记忆。跨块 KV 池随块数增长，必须按重要性淘汰旧块 KV，池容量上限直接决定可支持的总时长；超长视频必须接受远距离记忆衰减，后段场景漂移是结构性的，不是调参能消除的。</p>\n<p>第三条，它不解决块边界像素级无缝且零融合延迟的实时场景。重叠区加权融合与运动一致性检查需要 latent 在块间往返搬运并做同步，流式节奏被最慢块拖住；短块场景下调度开销占比过高，融合本身成为瓶颈。第四条，它不替代序列并行：序列并行用多卡换显存，本算法用时间（重复计算重叠帧）换显存，两者可以叠加，但解决的是不同维度的约束。</p>\n<p>还有一个容易被忽略的边界：运动一致性检查只能拦截不能修复。重叠帧比例设置过低时，块边界缺少足够运动上下文，融合后仍会出现接缝与速度突变，检查器能报出异常，却无法把丢失的运动信息补回来。因此重叠帧数不少于运动周期所需上下文，是一条硬约束而非建议值。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-4\">四 · 融合公式与它的工程含义</h3>\n<p>重叠区的处理不是简单平均，而是按时间距离加权：</p>\n<div class=\"formula\">$$z_t=\\frac{\\sum_{k\\in\\{b-1,b\\}} w_k(t)\\,z_{k,t}}{\\sum_{k} w_k(t)},\\quad w_k(t)=\\exp(-|t-t_k|/\\tau)$$</div>\n<p>其中 $z_{k,t}$ 为第 $k$ 块在时刻 $t$ 的 latent，$t_k$ 为该块锚点时间位置，$\\tau$ 控制时间距离衰减强度。越靠近块中心的帧权重越高，边界帧由两块共同平滑。这条公式的工程含义有三层：其一，$\\tau$ 太小则融合退化为硬切换，接缝回归；$\\tau$ 太大则边界帧被两块过度平均，运动细节被抹平。其二，权重计算是逐帧的，融合必须在 latent 空间完成而非像素空间，否则 VAE 的非线性会放大边界差异。其三，融合需要两块的重叠帧 latent 同时在手，这直接推高了显存峰值——重叠帧缓存待融合，正是显存预算里不可忽略的一项。</p>\n<p>与之配套的是流式解码策略：块生成后仅对非重叠新帧做 VAE 解码并流式输出，重叠帧缓存待融合。这样首帧时延被压缩到“首块采样 + 首块新帧解码”，而不必等整块融合完成。代价是重叠帧的 VAE 解码被推迟，融合与检查引入 CPU/GPU 同步，流式节奏受最慢块限制。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-5\">五 · 吞吐折减与批大小的联动</h3>\n<p>重叠帧是重复计算，吞吐折减可以定性写成：重叠帧占比 $r$ 时，有效吞吐约按 $1/(1+r)$ 折减。这个式子决定了负载配方的形态：请求形态是长时长、固定分辨率、固定采样步数，批大小受单块窗口显存约束而非总时长约束；重叠比例越高，单块计算量越大，批大小需按重叠帧数与块帧数的比值折减。也就是说，调高重叠比例换连续性，必须同时接受批大小下降带来的吞吐损失，两者是同一笔账。</p>\n<p>具体例子：同一张卡上，若单块窗口在无重叠时能驻留若干请求的批，加入重叠帧后单块 latent 与 KV 占用上升，批大小必须相应下调，否则显存溢出；而下调批大小又进一步压低吞吐。工程判断因此落在“重叠帧数取运动周期所需的最小上下文”这一原则上——够用即止，多出的重叠帧只买来边际递减的连续性收益，却按 $1/(1+r)$ 线性吃掉吞吐。</p>\n<p>SLO 由三项组成：首帧时延、块间帧间隔与端到端时长。首帧时延由 $T_{\\text{chunk}}+T_{\\text{VAE}}$ 主导，块间帧间隔由最慢块与融合同步开销主导，端到端时长则由块数与单块时间共同决定。三项 SLO 对重叠比例的敏感方向并不一致：提高重叠改善块间帧间隔的稳定性，却恶化首帧时延与端到端时长。容量规划必须按这三项分别定预算，而不是用一个平均吞吐数糊过去。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-6\">六 · 适用边界的工程判据</h3>\n<p>把上述约束收拢成几条可执行的判据。硬件档位按单块窗口能否驻留决定，通常单卡或单节点多卡即可，不需要跨节点并行；显存预算等于单块 latent 加跨块 KV 池加 VAE 解码工作区，三项中任何一项超限都要先解决它，而不是靠调重叠比例绕过。KV 策略是跨块 KV 池加重要性淘汰，池容量上限直接决定可支持的总时长；若重要性估计只看注意力幅值，会误删承载远距离场景记忆的 KV，导致长视频后段场景漂移，因此淘汰策略必须把场景级记忆纳入考量。</p>\n<p>稳定性技巧有三条：重叠帧数不少于运动周期所需上下文；融合权重按时间距离平滑；融合后做运动一致性检查以拦截块间速度突变。三条缺一，失败模式就会以接缝、速度突变或场景漂移的形式回归。最后一条工程判断是：当请求的块边界像素级无缝要求极高且不允许任何融合延迟时，本算法不适用——此时应转向逐帧因果生成路线，用因果掩码替代重叠融合，接受块内双向注意力的损失。反过来，只要总时长可远超单次注意力窗口、且允许块间存在融合延迟，分块重叠流式生成就是用时间换显存的最直接手段。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-7\">七 · 边界不在时长，而在“重叠预算”与“KV 记忆”两条硬约束</h3>\n<p>这套编排真正解决的，是单次 DiT 时空注意力窗口与显存装不下整段视频、而朴素等长切块又在块边界留下接缝与速度突变的那类请求。它不解决单块内部注意力本身的效率问题——计算图没有改动，也不解决多卡并行换显存的问题，那是序列并行的事；它用时间换显存。因此判断一个请求是否落在适用边界内，先看两个量：重叠帧占比 $r$ 与跨块 KV 池容量。前者决定吞吐，后者决定可支持的总时长上限。有效吞吐约按 $1/(1+r)$ 折减，重叠越多，单块计算量越大，批大小必须按重叠帧数与块帧数的比值折减，批大小受单块窗口显存约束而非总时长约束。当 $r$ 被压到很低以保吞吐时，块边界缺少足够运动上下文，融合后接缝与速度突变依然存在，而运动一致性检查只能拦截、不能修复。</p>\n<p>线上最典型的翻车不是显存 OOM，而是“越到后面越漂”。跨块 KV 池按重要性淘汰旧块时，若重要性只看注意力幅值，承载远距离场景记忆的 KV 会被误删，长视频后段出现场景漂移与人物外观跳变；这类故障在首帧时延和块间帧间隔两项 SLO 上都看不出来，只在端到端时长与人工抽检中暴露。融合本身也有系统代价：重叠区加权融合与运动检查需要 latent 在块间往返搬运并做 CPU/GPU 同步，流式节奏被最慢块拖住，短块场景下调度开销占比过高。融合权重按时间距离平滑，越靠近块中心权重越高，边界帧由两块共同平滑：</p>\n<div class=\"formula\">$$z_t=\\frac{\\sum_{k\\in\\{b-1,b\\}} w_k(t)\\,z_{k,t}}{\\sum_{k} w_k(t)},\\quad w_k(t)=\\exp(-|t-t_k|/\\tau)$$</div>\n<p>$\\tau$ 控制衰减强度，它与重叠帧数共同构成“运动周期所需上下文”的下限——重叠帧数少于该下限，融合只是在平滑一条本就不连续的轨迹。显存预算等于单块 latent 加跨块 KV 池加 VAE 解码工作区，池容量上限直接决定可支持的总时长；量化用 FP8/NVFP4 压单块激活与 KV 占用，但压不出池的容量上限。工程判断很直接：对块边界像素级无缝要求极高、且不允许任何融合延迟的实时场景，不应选这条路线；可接受远距离记忆衰减、以首帧时延与块间帧间隔为主要 SLO 的长时长固定分辨率请求，才是它的落点。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测信号</th><th>系统代价</th></tr></thead><tbody><tr><td>重叠帧不足</td><td>边界接缝、速度突变</td><td>检查只能拦截，需重跑该块</td></tr><tr><td>KV 淘汰过早</td><td>后段场景漂移</td><td>池扩容挤占单块显存</td></tr><tr><td>融合同步过重</td><td>块间帧间隔抖动</td><td>节奏受最慢块限制</td></tr></tbody></table>\n<h3 id=\"alg-chunk-overlap-long-video-sec-8\">八 · 切块与锚点登记：请求进入时的第一次显存裁决</h3>\n<p>请求到达调度器时，第一件事不是分配整段视频的 latent 张量，而是把总帧数按固定帧数切成块序列，并为每块登记重叠锚点的位置。设块长为 <em>L</em> 帧、重叠帧数为 <em>N</em><sub>overlap</sub>，则相邻块起点步进为 <em>L</em>−<em>N</em><sub>overlap</sub>，块数 <em>B</em>=⌈(<em>T</em>−<em>N</em><sub>overlap</sub>)/(<em>L</em>−<em>N</em><sub>overlap</sub>)⌉。这一步的输出是一张块表：每块的首帧绝对时间位置、重叠区间、锚点帧索引，以及该块将被允许写入的 KV 池槽位编号。代价集中在显存预算的第一次裁决上——单块 latent 加 VAE 解码工作区加跨块 KV 池上限，三者之和决定这个请求能否被接纳；批大小因此受单块窗口约束而非总时长约束，总时长只影响块数 <em>B</em> 与 KV 池的淘汰压力。工程上这一步是纯 CPU 侧的簿记，但它决定了后续所有 GPU 侧动作的并行度：块表一旦生成，块间无数据依赖的部分（非重叠新帧的 VAE 解码）就可以与下一块的采样重叠排布。</p>\n<p>锚点登记还有一个容易被忽略的输入：运动周期所需上下文。重叠帧数不得少于该分辨率与帧率下主体运动一个周期所跨越的帧数，否则锚点里根本没有可对齐的运动相位。这个下界不是靠调参试出来的，而是由块表在接纳阶段做硬校验——重叠不足的请求要么被拒绝，要么被提升重叠比例并相应折减批大小。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-9\">九 · 条件采样：重叠帧 KV 与 latent 如何进入单块计算图</h3>\n<p>每块进入 DiT 采样时，输入有三路：本块待生成的噪声 latent、上一块遗留的重叠帧 latent、以及重叠帧对应的 KV cache。注意这里不改变单次注意力的计算图——块内仍是完整的双向时空注意力，重叠帧的 KV 是作为额外上下文拼接进注意力的键值序列，而不是把注意力改成因果掩码。伪代码层面的顺序是：先把重叠帧 latent 编码为条件 token，与本块 token 在序列维拼接；注意力内核读取拼接后的 KV 序列，其中重叠段 KV 直接从跨块池中取，不重新计算。输出是本块全部 <em>L</em> 帧的 latent，其中前 <em>N</em><sub>overlap</sub> 帧与上一块重叠、需要后续融合，后 <em>L</em>−<em>N</em><sub>overlap</sub> 帧是新帧。</p>\n<p>代价有两层。计算层：重叠帧虽然复用 KV，但其 latent 仍要参与本块注意力的 query 侧计算，重复计算量正比于 <em>N</em><sub>overlap</sub>/<em>L</em>；有效吞吐按 <em>r</em>=<em>N</em><sub>overlap</sub>/(<em>L</em>−<em>N</em><sub>overlap</sub>) 折减为约 1/(1+<em>r</em>)。带宽层：跨块池取 KV 是一次显存读，块内注意力的 KV 驻留是另一次；在 FP8/NVFP4 量化下这两次读的字节数被压缩，但拼接后的序列变长会抬高注意力内核的片上缓冲需求，单块窗口能否驻留因此成为硬件档位的判据。具体例子：固定分辨率、固定采样步数的长时长请求，批大小按重叠帧数与块帧数的比值折减后，单卡即可驻留单块窗口，多卡并行只用于缩短单块时延而非扩大总时长。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-10\">十 · 新帧解码与流式输出：把 VAE 从关键路径上摘出来</h3>\n<p>块采样完成后，只对非重叠新帧做 VAE 解码并立即推流，重叠帧的 latent 留在缓存里等融合。这一步的输入是本块后 <em>L</em>−<em>N</em><sub>overlap</sub> 帧 latent，输出是解码后的像素帧序列，按帧间隔节奏写出。首帧时延的构成是 <em>T</em><sub>chunk</sub>+<em>T</em><sub>VAE</sub>：一块的采样时间加一次 VAE 解码时间，这就是流式体验的启动代价；此后稳态的块间帧间隔由最慢块决定，而不是由平均块决定。</p>\n<p>把 VAE 限定在新帧上是这个机制在吞吐上的关键取舍：重叠帧不解码，省下的解码算力正比于重叠比例，但代价是重叠帧的像素始终缺席，融合只能发生在 latent 域。这也解释了为什么融合权重必须平滑——latent 域的边界不连续在解码后会被 VAE 的感受野放大成可见接缝。工程判断上，VAE 解码工作区要与单块 latent 分开计入显存预算，否则在长时长请求下会把本已紧张的 KV 池挤掉，触发过早淘汰。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-11\">十一 · 重叠区加权融合与运动一致性检查</h3>\n<p>相邻两块都产出重叠区 latent 后，按时间距离加权融合：</p>\n<div class=\"formula\">$$z_t=\\frac{\\sum_{k\\in\\{b-1,b\\}} w_k(t)\\,z_{k,t}}{\\sum_{k} w_k(t)},\\quad w_k(t)=\\exp(-|t-t_k|/\\tau)$$</div>\n<p>其中 <em>z</em><sub>k,t</sub> 是第 <em>k</em> 块在时刻 <em>t</em> 的 latent，<em>t</em><sub>k</sub> 是该块锚点的时间位置，<em>τ</em> 控制时间距离衰减强度。越靠近块中心的帧权重越高，边界帧由两块共同平滑，因此融合后的边界不会偏向任何一块的独立推断。这一步的输入是两块重叠区的 latent 与各自锚点位置，输出是融合后的重叠区 latent，写回缓存供下一次解码或后续块条件使用。</p>\n<p>融合之后必须做运动一致性检查：在重叠区估计帧间位移或光流的一阶差分，若跨块处出现速度突变超过阈值，则判定该块衔接失败。检查只能拦截不能修复——这是失败模式里写明的边界。代价是同步开销：融合与检查需要 latent 在块间往返搬运并做 CPU/GPU 同步，流式节奏被最慢块拖住；短块场景下这部分调度开销占比过高，甚至超过采样本身。因此融合权重的时间衰减常数 <em>τ</em> 要与块长匹配，<em>τ</em> 过大则边界帧权重接近均分、平滑过度导致运动模糊，<em>τ</em> 过小则退化为硬切。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-12\">十二 · 跨块 KV 池的写入、读取与淘汰</h3>\n<p>每块采样结束后，本块新帧的 KV 写入跨块池，重叠帧 KV 去重后保留一份。池的容量上限直接决定可支持的总时长，这是整个机制规模上限的显存侧根源。淘汰按重要性进行，但重要性估计不能只看注意力幅值：承载远距离场景记忆的 KV 往往注意力幅值不高却在后续块中被反复读取，只看幅值会误删它们，表现为长视频后段的场景漂移。可行的做法是把“被后续块读取次数”与“注意力幅值”合成一个分数，并对锚点帧 KV 设保护位。</p>\n<p>代价曲线是：池随块数增长，淘汰策略的复杂度随池容量上升，而每次淘汰都可能触发一次显存重排；在超长视频上，远距离记忆衰减是必须接受的定性代价，而不是可以靠加大池容量消除的缺陷。表里给出各步骤的输入输出与主要代价归属，便于在容量规划时定位瓶颈。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>切块与锚点登记</td><td>总帧数、分辨率、帧率</td><td>块表、锚点索引、池槽位</td><td>显存预算裁决，决定批大小</td></tr><tr><td>条件采样</td><td>噪声 latent、重叠 latent、重叠 KV</td><td>本块全部帧 latent</td><td>重复计算 ∝ 重叠比例，吞吐按 1/(1+<em>r</em>) 折减</td></tr><tr><td>新帧解码推流</td><td>非重叠新帧 latent</td><td>像素帧序列</td><td>首帧时延 <em>T</em><sub>chunk</sub>+<em>T</em><sub>VAE</sub>，节奏受最慢块限制</td></tr><tr><td>加权融合与检查</td><td>两块重叠 latent、锚点位置</td><td>融合 latent、一致性判定</td><td>CPU/GPU 同步，短块下调度占比高</td></tr><tr><td>KV 池维护</td><td>新帧 KV、读取计数</td><td>池内容、淘汰结果</td><td>池容量决定总时长上限，误删致场景漂移</td></tr></tbody></table>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-13\">十三 · 步骤间的依赖与流水排布</h3>\n<p>按数据流看，块 <em>b</em> 的采样依赖块 <em>b</em>−1 的重叠 latent 与 KV，因此采样是串行的；但块 <em>b</em>−1 的新帧解码与块 <em>b</em> 的采样之间没有数据依赖，可以并行排布，这正是把 VAE 从关键路径上摘出来的调度依据。融合则夹在采样与下一次条件使用之间，是一个必须同步的汇合点。流水排布的目标是让最慢块不落在关键路径上：若某块因重叠区运动复杂而采样步数不变但融合检查耗时上升，调度器应把它的解码提前，用解码时间掩盖检查时间。</p>\n<p>这里落到一个具体工程判断：重叠帧数、融合衰减常数 <em>τ</em>、KV 池淘汰阈值三者必须一起调，单独调任何一个都会把代价转移到别的步骤上——加大重叠改善接缝但压低吞吐并抬高池写入量，收紧淘汰省显存但牺牲远距离一致性，调大 <em>τ</em> 平滑边界但引入运动模糊。稳定性技巧的落点是重叠帧数不少于运动周期所需上下文、权重按时间距离平滑、融合后做一致性检查拦截速度突变；三者共同构成块间衔接的可接受判据，而判据一旦不满足，机制的选择是把该块标记为需重采样而非放行。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-14\">十四 · 边界条件、失效路径与每步的系统代价</h3>\n<p>这套编排的失效不是随机噪声，而是由三个可量化的边界共同决定：重叠帧占比 <i>r</i>、跨块 KV 池容量 <i>C</i><sub>kv</sub>、以及融合同步点数量。吞吐折减关系为 <span class=\"formula\">$$\\text{throughput}_{\\text{eff}}\\approx\\frac{1}{1+r}\\cdot\\text{throughput}_{\\text{single}},\\quad \\text{mem}_{\\text{budget}}=M_{\\text{latent}}+C_{\\text{kv}}\\cdot s_{\\text{kv}}+M_{\\text{vae}}$$</span>，其中 <i>s</i><sub>kv</sub> 为单块 KV 字节数。当 <i>r</i> 从 0.1 抬到 0.3，单块采样步数不变但每块帧数增加，DiT 前向的 token 数按 (1+<i>r</i>) 放大，注意力计算量近似二次增长，单块时延上升幅度超过线性；而 <i>C</i><sub>kv</sub> 一旦被填满，淘汰策略开始生效，此时总时长上限不再由算力决定，而由显存里能留住多少块锚点决定。工程判断是：先按目标时长反推所需锚点数，再决定 <i>r</i>，而不是先定 <i>r</i> 再看能跑多长。</p>\n<p>逐步看代价，切块步骤本身是纯 CPU 索引运算，代价可忽略，但它决定了后续所有步骤的显存上界；条件采样步骤是唯一的重计算段，输入为重叠帧 latent 与 KV、输出为新块 latent，代价是 <i>T</i><sub>chunk</sub> 量级的 DiT 前向，且随 <i>r</i> 放大；VAE 解码只作用于非重叠新帧，这是流式首帧时延 <i>T</i><sub>chunk</sub>+<i>T</i><sub>VAE</sub> 的主要构成，解码工作区 <i>M</i><sub>vae</sub> 与分辨率成正比而与总时长无关，这正是该方案能把显存钉死在单块窗口的原因。融合步骤是纯 latent 加权，公式为 <span class=\"formula\">$$z_t=\\frac{\\sum_{k\\in\\{b-1,b\\}} w_k(t)\\,z_{k,t}}{\\sum_{k} w_k(t)},\\quad w_k(t)=\\exp(-|t-t_k|/\\tau)$$</span>，计算量小但必须等两块 latent 都就位，构成一个 GPU→CPU→GPU 的同步点；<i>τ</i> 越小，边界帧越偏向单块，接缝风险上升，<i>τ</i> 越大则融合区被拉宽，运动细节被过度平滑。运动一致性检查是第三类代价：它拦截速度突变却不修复，属于“只报错不纠错”的守门员，检查本身引入额外同步，短块场景下调度开销占比会显著上升。</p>\n<p>三类典型失效值得单独列出。<b>重叠不足</b>：当重叠帧数少于运动周期所需上下文时，边界处两块对同一运动的相位估计不一致，融合后仍出现接缝与速度突变，此时一致性检查只能标记而不能补救，唯一出路是回退增大 <i>r</i> 并重跑该块。<b>淘汰误删</b>：跨块 KV 池若只按注意力幅值估计重要性，会优先丢弃幅值低但承载远距离场景记忆的 KV，表现为长视频后段场景漂移、主体外观缓慢变化，这类退化在单帧上不可见，只在跨块比对时暴露。<b>节奏拖累</b>：流式输出的块间帧间隔由最慢块决定，任一块的融合或检查同步超时都会让整条流水线停等，块越短，固定同步开销占比越高，实时性越难保证。因此该方案不适合对块边界像素级无缝且不允许任何融合延迟的实时场景；它的正确用法是把 <i>r</i> 与 <i>C</i><sub>kv</sub> 作为一对联合调参量，用吞吐换时长，并接受超长视频上的远距离记忆衰减。</p>\n<h3 id=\"alg-chunk-overlap-long-video-sec-15\">十五 · 融合公式的逐项解剖与衰减核的由来</h3>\n<p>重叠区融合写成两块的加权平均，但每一项都有明确的物理含义，不是随手取的平滑滤波器。公式为</p>\n<div class=\"formula\">$$z_t=\\frac{\\sum_{k\\in\\{b-1,b\\}} w_k(t)\\,z_{k,t}}{\\sum_{k} w_k(t)},\\quad w_k(t)=\\exp(-|t-t_k|/\\tau)$$</div>\n<p>其中 $z_{k,t}$ 是第 $k$ 块在全局时刻 $t$ 的 latent，$t_k$ 是该块的锚点时间位置（通常取块中心或块首），$\\tau$ 是时间距离衰减常数。分子是两块 latent 的加权和，分母是权重归一化项——这一项不能省，因为重叠区内两块都贡献权重，若不归一化会整体抬亮 latent 幅值，解码后表现为重叠段亮度跳变。指数核的选择来自一个直接约束：权重必须随离锚点距离单调下降且在锚点处取最大值 1，指数函数是满足该约束且只有一个可调参数 $\\tau$ 的最简形式。$\\tau$ 的取值决定融合的“软硬”：$\\tau$ 远小于重叠帧数时，权重在重叠区中部就衰减到接近零，等效于硬切，接缝回归；$\\tau$ 与重叠帧数同量级时，重叠区中部两块权重接近相等，过渡最平滑，但两块 latent 若存在系统性偏差（例如运动相位不一致），等权混合会产生重影。工程上把 $\\tau$ 绑定到重叠帧数 $N_{\\text{overlap}}$ 的一个比例，使权重曲线在重叠区两端恰好衰减到可忽略的水平。</p>\n<p>推导的关键一步是把“块边界不连续”转化为“权重函数在边界处的一阶连续性”。设块 $b-1$ 的有效区间终止于 $t_e$，块 $b$ 起始于 $t_s$，重叠区为 $[t_s,t_e]$。要求融合结果在 $t_s$ 处完全等于块 $b$ 的 latent、在 $t_e$ 处完全等于块 $b-1$ 的 latent，即 $w_{b-1}(t_s)\\to 0$、$w_b(t_e)\\to 0$。指数核在 $|t-t_k|$ 增大时单调趋零，只要 $\\tau$ 使得 $\\exp(-(t_e-t_s)/\\tau)$ 足够小，两端条件即近似满足。这一步把“接缝”这个视觉现象换成了权重在重叠区端点趋零的数值条件，从而可以直接在 latent 空间做融合而不需要像素级后处理。代价是：重叠区每一帧都要做两次加权乘加与一次除法，融合本身是访存密集型操作，重叠比例 $r$ 越高，这部分额外访存占单块解码工作区的比例越大，是吞吐按 $1/(1+r)$ 折减之外的第二重开销。</p>\n<p>具体例子：设块长 48 帧、重叠 8 帧，$\\tau$ 取 3 帧。重叠区第 1 帧离块 $b$ 锚点近，权重约 0.7 对 0.3；重叠区第 4 帧两块权重接近 0.5 对 0.5；第 8 帧权重反转为 0.3 对 0.7。这样块 $b-1$ 的尾部运动趋势被逐渐让渡给块 $b$ 的头部，速度矢量在重叠区内插过渡，而不是在单帧处突变。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-16\">十六 · 首块时延的分解与流式节奏的瓶颈项</h3>\n<p>首块时延的近似式是</p>\n<div class=\"formula\">$$\\text{latency}_{\\text{first chunk}}\\approx T_{\\text{chunk}}+T_{\\text{VAE}}$$</div>\n<p>$T_{\\text{chunk}}$ 是单块扩散/流匹配采样的总时间，等于采样步数乘以单步前向时间；$T_{\\text{VAE}}$ 是首块非重叠新帧的 VAE 解码时间。这个近似刻意忽略了块间 KV 池读写与融合同步，因为首块没有前驱块，KV 池为空、融合为空，两项为零。逐项看：$T_{\\text{chunk}}$ 与块帧数、分辨率、采样步数成正比，且受单块窗口显存约束——块越大，单步前向的激活占用越高，能并行的批越小；$T_{\\text{VAE}}$ 只作用于非重叠新帧，因此重叠帧越多，首块需要解码的帧越少，$T_{\\text{VAE}}$ 反而下降，但 $T_{\\text{chunk}}$ 因块内含重叠帧而上升，两者方向相反。首块时延的最优点不在重叠为零处，而在“重叠带来的 $T_{\\text{chunk}}$ 增量”与“$T_{\\text{VAE}}$ 减量”相抵的位置附近，具体位置由 VAE 解码吞吐与 DiT 单步吞吐的比值决定。</p>\n<p>流式输出阶段，块间帧间隔不由 $T_{\\text{chunk}}+T_{\\text{VAE}}$ 决定，而由“最慢块”决定：某块若因 KV 池淘汰触发重算、或因运动一致性检查不通过触发局部重采样，该块的完成时间就会拖长整条流水线。这就是材料中“流式输出节奏受最慢块限制”的机制来源。工程上的应对不是消除慢块，而是把慢块的影响局部化——让后续块在等待期间继续用已缓存的锚点 KV 做条件准备，把同步点从“每块结束”推到“融合写入前”。代价是 KV 池在等待期间多驻留一份锚点副本，显存预算里要为这个缓冲留出余量。</p>\n<p>具体例子：首块 48 帧、重叠 8 帧，非重叠新帧 40 帧。若 VAE 解码吞吐高于 DiT 单步吞吐，则 $T_{\\text{VAE}}$ 在首块时延中占比小，优化重点应放在减少采样步数或降低单步激活占用上；反之若 VAE 是瓶颈，则应把重叠帧数调高以压缩首块需解码的帧数，代价是 $T_{\\text{chunk}}$ 上升。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-17\">十七 · 显存上界的构成与 KV 池容量对总时长的硬约束</h3>\n<p>显存关系写成</p>\n<div class=\"formula\">$$\\text{mem}\\propto N_{\\text{overlap}}$$</div>\n<p>这个比例关系的完整含义是：单块工作集由三部分组成——单块 latent（含重叠帧）、跨块 KV 池、VAE 解码工作区。其中单块 latent 与 $N_{\\text{overlap}}$ 成正比，因为重叠帧要同时保留两块的条件副本以供融合；KV 池则与已生成块数成正比，是随总时长增长的那一项。因此“显存需求限制在单块窗口内”只在 KV 池被淘汰策略封顶时才成立。池容量上限 $C_{\\text{KV}}$ 直接决定可支持的总时长：若每块贡献的 KV 条目数为 $m$，则最多保留 $\\lfloor C_{\\text{KV}}/m\\rfloor$ 块的 KV，超出部分按重要性淘汰。这意味着总时长上限不是一个固定帧数，而是“池容量除以每块 KV 占用”再乘以块长——调高块长会减少块数、放缓池增长，但抬高单块 latent 占用；调低块长则相反。两个方向都受 $N_{\\text{overlap}}$ 牵制，因为重叠帧同时进入单块 latent 和 KV 池。</p>\n<p>推导的关键一步是把“远距离一致性”折算成“被保留的锚点块数”。跨块条件锚定依赖重叠帧的 KV 作为上下文，若某块的 KV 被淘汰，后续块就失去了对该块内容的直接引用，只能靠 latent 融合的间接痕迹维持一致性。因此重要性淘汰的判据不能只看注意力幅值——幅值低的 KV 可能承载的是低频场景记忆（背景、全局光照），它们在单步注意力中贡献小，但对长视频后段的场景漂移起决定作用。材料指出的失败模式正是这一点：只看幅值会误删远距离场景记忆。可行的替代判据是把“该 KV 所属块距当前块的时间距离”与“该块 latent 在融合中被引用的次数”一起纳入重要性，让远距离但被反复锚定的块获得保留优先权。</p>\n<p>具体例子：设池容量允许保留 6 块 KV，块长 48 帧、重叠 8 帧，则池覆盖的时间跨度约为 6×(48−8)+8 帧的有效新内容。若总时长需要 20 块，则第 7 块之后必须开始淘汰，此时远距离一致性从“直接锚定”退化为“融合痕迹 + 淘汰判据保留的少量远块 KV”，后段场景漂移的风险随块数增加而上升。这是算法适用边界里“超长视频需接受远距离记忆衰减”的显存侧根源。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-18\">十八 · 吞吐折减的推导与批大小的折减配方</h3>\n<p>重叠帧占比 $r=N_{\\text{overlap}}/N_{\\text{chunk}}$ 时，有效吞吐按 $1/(1+r)$ 折减。推导很直接：每块实际计算 $N_{\\text{chunk}}$ 帧，但只有 $N_{\\text{chunk}}-N_{\\text{overlap}}$ 帧是新增输出，因此单位新增输出的计算量为 $N_{\\text{chunk}}/(N_{\\text{chunk}}-N_{\\text{overlap}})=1/(1-r)$，反过来单位计算量产出的新增帧为 $1-r$；把重叠帧视为纯开销时，等效吞吐折减因子即 $1/(1+r)$ 的形式（两种写法在 $r$ 较小时数值接近，工程上按前者估算更保守）。这个折减是线性的，没有饱和点——重叠比例翻倍，吞吐近似减半，因此重叠帧数不能靠“多留一点更保险”来定，必须由运动周期所需上下文决定下限，再由 SLO 的块间帧间隔决定上限。</p>\n<p>批大小的折减配方由此而来：批大小受单块窗口显存约束而非总时长约束，因此可并行的请求数正比于单块窗口能容纳的 latent 数除以单请求单块 latent 占用。重叠帧抬高单请求占用，批大小需按 $N_{\\text{overlap}}$ 与 $N_{\\text{chunk}}$ 的比值折减。伪代码思路如下：</p>\n<ul>\n<li>输入：总帧数 $F$、块长 $N_c$、重叠 $N_o$、采样步数 $S$、SLO 三元组（首帧时延、块间帧间隔、端到端时长）。</li>\n<li>计算块数 $B=\\lceil (F-N_o)/(N_c-N_o)\\rceil$，首块覆盖 $[0,N_c)$，第 $b$ 块覆盖 $[b(N_c-N_o),\\,b(N_c-N_o)+N_c)$。</li>\n<li>对每块：取前一块重叠区 latent 与 KV 作为条件，跑 $S$ 步采样；仅对索引 $\\ge$ 本块起始 $+N_o$ 的帧做 VAE 解码并推流；重叠区 latent 写入融合缓冲。</li>\n<li>融合：对重叠区每帧按 $w_k(t)=\\exp(-|t-t_k|/\\tau)$ 计算两块权重，归一化后写回全局 latent 序列。</li>\n<li>运动检查：比较重叠区融合前后相邻帧 latent 差分的范数，超过阈值则标记该块并触发局部重采样（只重跑重叠区尾部若干步）。</li>\n<li>KV 池维护：新块 KV 入池，按“时间距离 + 被引用次数”排序，超容量时淘汰末位。</li>\n<li>批调度：可用批大小 $=\\lfloor \\text{单块窗口显存预算}/(\\text{单块 latent}(N_c)+\\text{KV 池均摊}) \\rfloor$，再乘以 $(1-r)$ 的折减系数。</li>\n</ul>\n<p>代价落在两处：融合与运动检查需要 latent 在块间往返搬运并做 CPU/GPU 同步，短块场景下这部分调度开销占比过高，甚至超过采样本身；KV 池的排序与淘汰在每块结束时执行，若池容量大、块数多，排序本身成为不可忽略的固定开销。具体例子：块长 48、重叠 8 时 $r\\approx0.17$，吞吐折减约一成半；若把重叠提到 16 帧，$r\\approx0.5$，吞吐近乎腰斩，而运动连续性的边际改善在重叠超过运动周期所需上下文后迅速变小——这就是重叠比例必须由运动周期而非“越多越好”来定的定量理由。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-19\">十九 · 运动一致性检查的判据与不可修复性</h3>\n<p>运动一致性检查在融合之后执行，判据是重叠区相邻帧 latent 差分的范数与块内同位置的差分范数之比。设重叠区第 $t$ 帧的融合结果为 $z_t$，定义速度代理 $v_t=\\|z_t-z_{t-1}\\|$，检查条件为 $v_t$ 落在块 $b-1$ 尾部与块 $b$ 头部各自 $v$ 的包络之内；超出包络即判定为块间速度突变。这一步的必要性来自融合公式的局限：加权平均只能平滑幅值，不能修正两块运动相位不一致导致的“方向错位”——若块 $b$ 的头部把运动理解成与块 $b-1$ 尾部相反的方向，等权混合会产生一帧静止或倒退的中间态，视觉上是顿挫而非接缝。检查能拦截这种情形，但材料明确指出它只能拦截不能修复：拦截后的动作是局部重采样，而重采样的条件仍来自同一组锚点 KV，若锚点本身相位有偏，重采样只能换一个随机种子碰运气，不能保证收敛。</p>\n<p>因此工程判断是：把运动一致性的保障前移到锚点选择上，而不是依赖后置检查。具体做法是让重叠帧数不少于运动周期所需上下文——若场景中存在周期为 $P$ 帧的运动（如旋转、往复摆动），重叠帧数应覆盖至少半个周期，使块 $b$ 在起始处就能看到块 $b-1$ 的完整相位，从而在采样阶段而非融合阶段对齐运动。代价是重叠帧数下限被运动内容抬高，吞吐折减随之固定在一个不低于该下限的水平；对运动周期长的素材，这个下限可能逼近块长的一半，此时应改用更长的块而非更高的重叠比例，因为块长增加不改变 $r$ 但减少了块数与 KV 池增长。</p>\n<p>具体例子：一段包含慢速摇镜的视频，运动周期约 24 帧。若块长 48、重叠 8，块 $b$ 起始处只能看到块 $b-1$ 尾部 8 帧的相位，不足半个周期，融合后摇镜速度在边界处出现可测的突变，检查会拦截并触发重采样，但重采样仍缺相位上下文，表现为边界附近反复重试、块间帧间隔被拉长。把重叠提到 16 帧后，块 $b$ 起始处可见相位覆盖大半个周期，采样阶段即可对齐，检查通过率上升，代价是吞吐折减从一成半升到三成。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-20\">二十 · 与相邻算法的公式级分野</h3>\n<p>本算法的公式结构决定了它与相邻方法的分野不在计算图，而在条件注入的位置。纯自回归 Rolling Forcing 类方法的连续性来自逐帧因果生成：第 $t$ 帧以 $1..t-1$ 帧为条件，公式上是单向条件链，没有融合项，因此不存在 $w_k(t)$ 与 $\\tau$；它的代价是块内双向注意力被放弃，长程一致性靠 KV 因果链维持，KV 池同样随帧数增长。序列并行则把单次注意力的时间维切到多卡，公式上不引入重叠与融合，显存靠多卡分摊而非时间分块，通信量随切分数上升。本算法保留块内双向注意力，用重叠帧 KV/latent 做跨块条件锚定，公式上多出融合核与归一化项，代价是重叠计算与融合同步，收益是单卡即可支撑远超单次注意力窗口的时长。</p>\n<p>这个分野在部署配方上落成一条判断：硬件档位按单块窗口能否驻留决定，通常单卡或单节点多卡即可，不需要为时间维做跨节点切分；显存预算等于单块 latent 加跨块 KV 池加 VAE 解码工作区，其中 KV 池容量上限是唯一随总时长增长的项，也是唯一需要按重要性淘汰策略精细管理的项。量化（FP8/NVFP4）降低单块激活与 KV 占用，直接抬高池容量上限对应的可支持时长，但它不改变 $1/(1+r)$ 的吞吐折减——折减来自重叠帧的重复计算，与精度无关。因此容量规划的顺序是：先由运动周期定 $N_{\\text{overlap}}$ 下限，再由 SLO 的块间帧间隔定 $N_c$ 上限，最后由精度与池容量定可支持的总时长；三者中任何一项被反向调整，都会在另外两项上付出可计算的代价。</p>\n<h3 id=\"alg-chunk-overlap-long-video-sec-21\">二十一 · 请求形态的匹配面：长时长、定分辨率、定步数</h3>\n<p>分块重叠流式的负载配方，第一层筛选不是“视频生成”这个大类，而是三个维度同时被钉死的请求：总时长显著超出单次时空注意力窗口、分辨率在整条请求内不变、采样步数在块间不变。三者任一漂移，重叠锚定的前提就被破坏——分辨率变化会让重叠帧的 latent 网格对不上，融合权重无法在像素级对齐；步数变化会让块间 latent 处于不同的噪声水平，KV 锚点的语义不再是“同一轨迹上的邻近状态”。工程上这意味着调度器必须把这类请求从通用视频队列里摘出来，单独成池，否则混批会把定步数的块和变步数的块塞进同一个 continuous batch，重叠区的加权融合退化成跨噪声等级的插值。</p>\n<p>批大小的约束方向与常规 LLM 相反。LLM 的批大小受 KV cache 总量与总序列长度挤压，而这里批大小受<strong>单块窗口显存</strong>约束，与总时长解耦：总时长只影响跨块 KV 池的容量需求，不影响单次前向的激活峰值。设单块帧数 $F_b$、重叠帧数 $N_{\\text{overlap}}$、单帧 latent 显存 $m_f$、跨块 KV 池容量 $C_{\\text{kv}}$、VAE 解码工作区 $m_{\\text{vae}}$，则单副本显存预算为</p>\n<div class=\"formula\">$$\\text{mem}_{\\text{replica}} = F_b \\cdot m_f + C_{\\text{kv}} + m_{\\text{vae}},\\qquad B_{\\max} = \\left\\lfloor \\frac{M_{\\text{GPU}} - M_{\\text{resident}}}{\\text{mem}_{\\text{replica}}} \\right\\rfloor$$</div>\n<p>其中 $M_{\\text{resident}}$ 是权重与运行时固定开销。注意 $B_{\\max}$ 里没有出现总时长——这是该配方最容易被误配的地方：容量规划者按“时长越长越吃显存”的直觉去压批，实际压错了变量。真正随时长增长的是 $C_{\\text{kv}}$，它由淘汰策略的上限决定，而不是由批大小决定。</p>\n<p>具体例子：一条 4K 分辨率、固定 30 步采样、总长数十秒的请求，切成固定帧数的块并保留若干重叠帧。它的首帧时延由 $T_{\\text{chunk}}+T_{\\text{VAE}}$ 主导，端到端时长由块数乘以单块时间主导，块间帧间隔则由最慢块的完成时刻决定。三项 SLO 中，只有块间帧间隔对批大小敏感——批越大，单块完成越慢，流式节奏越抖。因此这类负载的正确配方是<strong>小批、多副本、按块流水</strong>，而不是大批堆吞吐。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-22\">二十二 · 长度分布：短请求是毒药，长尾才是主菜</h3>\n<p>重叠融合的固定成本与块数无关，与块边界数成正比。一条只够切两块、甚至一块就装下的“短长视频”，其开销结构是：重叠帧的重复计算照付、融合与运动一致性检查照做、跨块 KV 池的建立与淘汰逻辑照跑，但摊薄这些成本的新帧数量极少。设重叠帧占比 $r=N_{\\text{overlap}}/F_b$，有效吞吐按 $1/(1+r)$ 折减；当块数 $K$ 很小，实际折减还要叠加融合同步的固定开销，等效吞吐进一步下滑。</p>\n<p>于是长度分布直接决定这套编排是否划算。工程判断是给请求设一个<strong>最小块数门槛</strong>：块数低于阈值时走单次全窗口路径（若显存允许）或走无重叠的朴素切块，把重叠机制留给真正需要跨块锚定的长尾。这与调度器里的分桶逻辑耦合——按预估块数分桶，而不是按时长分桶，因为时长到块数的映射受分辨率与帧率影响，同一时长在不同分辨率下块数差一倍以上。</p>\n<p>长尾端的代价在 KV 池。池容量上限直接决定可支持的总时长，超长视频必须接受远距离记忆衰减。这里有一个负载侧的陷阱：长度分布若呈重尾，少数超长请求会长期占住 KV 池的高水位，把同副本上其他请求的池配额挤掉，表现为“同一批里短请求也开始出现后段场景漂移”。解法是按请求预分配池配额并做准入控制，而不是让池在全副本上自由竞争。</p>\n<p>具体例子：一个混合队列里既有数秒级短片又有分钟级长片。若不分池，短片被强制走重叠路径，付出融合同步开销却换不到连续性收益，块间帧间隔反而因为同步点变多而变差；长片则因为池被短片占用水位，淘汰策略提前触发，远距离场景记忆丢失。分池后，短片走低延迟路径，长片独占池配额，两类 SLO 才同时成立。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-23\">二十三 · 并发与批大小的折减公式</h3>\n<p>并发维度上，这套编排的并行粒度是“块流水线”而非“请求批”。同一副本内，多个请求的块可以交错执行以填满 SM，但每个块的采样必须等自己的重叠 KV 与 latent 就绪，形成数据依赖链。可交错的程度取决于块内计算量与块间同步开销的比值：块越大，单块计算越能盖住同步，交错越有效；块越小，同步占比越高，交错退化为串行等待。</p>\n<p>把批大小按重叠比例折减写成可执行的配方：</p>\n<div class=\"formula\">$$B_{\\text{eff}} = \\left\\lfloor B_{\\max} \\cdot \\frac{F_b}{F_b + N_{\\text{overlap}}} \\right\\rfloor = \\left\\lfloor \\frac{B_{\\max}}{1+r} \\right\\rfloor$$</div>\n<p>这个折减不是显存折减，而是<strong>时间折减</strong>：重叠帧的重复前向占用了本可用于其他请求的算力槽。若忽略这一步，直接把 $B_{\\max}$ 当批大小用，结果是单块完成时间被拉长，块间帧间隔超出 SLO，流式输出从“连续”退化为“一阵一阵”。反过来，若过度保守把批压到 1，SM 利用率在块间同步窗口内塌陷，端到端时长被拉长。配方点在于让 $B_{\\text{eff}}$ 与块内计算量匹配，使同步窗口恰好被其他请求的块填满。</p>\n<p>并发上限还有一条隐性约束：融合与运动一致性检查需要 latent 在块间往返搬运并做 CPU/GPU 同步。并发越高，同步点越多，主机侧调度开销线性增长。在短块场景下，这部分开销占比过高，表现为 GPU 利用率不低但吞吐上不去——典型的同步瓶颈而非算力瓶颈。量化（FP8/NVFP4 降低单块激活与 KV 占用）能抬高 $B_{\\max}$，但抬不动同步开销，所以量化收益在长块、低并发下最明显，在短块、高并发下被同步吃掉。</p>\n<p>具体例子：某副本按 $B_{\\max}$ 满批跑长片，块间帧间隔抖动明显；把批按 $1/(1+r)$ 折减后，单块时间回落，抖动收敛，端到端时长因块流水更顺反而略降。这说明折减公式不是保守，而是把算力从“堆在同一时刻”重新分配到“填满同步空隙”。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-24\">二十四 · 负载不对时的三种崩法</h3>\n<p>第一种崩法是重叠不足。重叠帧比例设置过低时，块边界缺少足够运动上下文，融合后仍会出现接缝与速度突变。关键在于运动一致性检查只能拦截不能修复：它能标记出块间速度突变的帧并触发重生成，但重生成本身要再走一遍采样，等于把失败成本翻倍。负载侧的表现是重试率上升，而重试又占用块流水槽，进一步拉长块间帧间隔，形成正反馈。重叠帧数不少于运动周期所需上下文是硬约束，不是可调参数。</p>\n<p>第二种崩法是 KV 池淘汰过早。跨块 KV 池按重要性淘汰旧块时，若重要性估计只看注意力幅值，会误删承载远距离场景记忆的 KV，导致长视频后段场景漂移。这类失败在负载画像上很隐蔽：单块时延、首帧时延、块间帧间隔三项 SLO 全部达标，唯独端到端质量在后段塌陷。它只在长尾请求上出现，且与并发正相关——并发越高，池水位越高，淘汰越早触发。工程上要把“池水位”作为独立监控项，而不是等质量指标报警。</p>\n<p>第三种崩法是同步拖累流式节奏。融合与检查引入的 CPU/GPU 同步使流式节奏受最慢块限制。当负载里混入少量超长块（例如分辨率不变但运动复杂度高的段落导致采样实际耗时更长），整个流水线被这一块钉住，其余块完成后只能等。表现为块间帧间隔的分布出现长尾，均值尚可但 P99 爆掉。对策是把块按预估耗时分层调度，让慢块提前起跑，而不是按到达顺序排队。</p>\n<p>三种崩法共享一个诊断信号：块间帧间隔的方差。方差扩大先于质量指标恶化出现，是负载配方失配的早期指示。把方差纳入调度器的反馈回路，比事后调重叠比例更省算力。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-25\">二十五 · 配方表与工程判断</h3>\n<p>把上述约束整理成一张可对照的配方表，按请求形态给出参数取向。表中不写具体数值，只写方向与耦合关系，因为数值取决于分辨率、帧率与硬件档位。</p>\n<table class=\"mini\"><thead><tr><th>请求形态</th><th>块数取向</th><th>重叠比例</th><th>批大小</th><th>主要风险</th></tr></thead><tbody>\n<tr><td>短片（块数低于门槛）</td><td>不分块或朴素切块</td><td>不启用</td><td>按单块窗口满批</td><td>强制走重叠路径导致同步开销白付</td></tr>\n<tr><td>中长片（块数适中）</td><td>固定帧数切块</td><td>满足运动周期上下文</td><td>按 $1/(1+r)$ 折减</td><td>重叠不足导致重试率上升</td></tr>\n<tr><td>超长片（重尾）</td><td>固定帧数切块</td><td>同上，不额外加大</td><td>小批多副本</td><td>KV 池水位挤压、远距离记忆衰减</td></tr>\n<tr><td>混合队列</td><td>按预估块数分桶</td><td>分池配置</td><td>分池配置</td><td>池配额竞争、块间帧间隔方差扩大</td></tr>\n</tbody></table>\n<p>配方表背后是一条工程判断：这套编排的容量规划变量是<strong>块数分布</strong>与<strong>池水位</strong>，不是总时长与总帧数。按总时长做容量规划会系统性高估显存需求、低估同步开销；按块数分布规划，才能把批大小、重叠比例、池配额三个旋钮解耦调节。硬件档位按单块窗口能否驻留决定，通常单卡或单节点多卡即可——这与序列并行用多卡换显存的路子相反，这里是用时间换显存，多卡只用来提副本数而非切分单块。</p>\n<p>最后落在具体机制上：调度器应在请求准入时计算预估块数与预估重叠占比，据此查表得到 $B_{\\text{eff}}$ 与池配额，并把块间帧间隔方差作为运行时反馈信号回写配方。负载不对时，最先崩的从来不是显存，而是块间帧间隔的方差；把方差当一等指标，比事后调重叠帧数更能守住 SLO。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-26\">二十六 · 负载配方：什么请求吃得住这套编排，什么请求会把它拖垮</h3>\n<p>这套分块重叠流式生成并非通用加速器，它的收益边界由请求形态决定。理想负载是<strong>长时长、固定分辨率、固定采样步数</strong>的视频生成请求：总帧数远超单次 DiT 时空注意力窗口，但每一块的帧数、latent 形状、采样步数在请求间保持一致，块间 KV 池的容量需求可预估、可复用。批大小在这里的约束条件与常规推理相反——它不由总时长决定，而由<strong>单块窗口显存</strong>决定，因为任一时刻只有一块的 latent 与激活驻留在计算路径上。显存预算可写成三项之和：单块 latent、跨块 KV 池、VAE 解码工作区；其中 KV 池上限直接决定可支持的总时长，是容量规划的第一约束。若请求时长分布离散、分辨率频繁跳变，块帧数与重叠帧数无法固定，KV 池的淘汰节奏被打乱，调度器就得为每个请求单独估算窗口，吞吐随之塌陷。</p>\n<p>重叠比例是负载配方的核心旋钮，也是吞吐的代价来源。设重叠帧占块帧数的比例为 $r$，每块实际计算量按 $1+r$ 放大，有效吞吐近似按 $1/(1+r)$ 折减：</p>\n<div class=\"formula\">$$\\text{throughput}_{\\text{eff}}\\approx\\frac{\\text{throughput}_{\\text{no-overlap}}}{1+r},\\quad r=\\frac{N_{\\text{overlap}}}{N_{\\text{chunk}}}$$</div>\n<p>因此批大小必须按 $N_{\\text{overlap}}/N_{\\text{chunk}}$ 折减，而不是按总帧数线性放大。重叠帧太少（$r$ 过低）时，块边界缺少足够的运动上下文，加权融合只能平滑 latent 而无法补出缺失的运动信息，接缝与速度突变仍会出现，运动一致性检查此时只能拦截、不能修复；重叠帧太多则单块计算量与显存同步上涨，流式首帧时延 $\\text{latency}_{\\text{first chunk}}\\approx T_{\\text{chunk}}+T_{\\text{VAE}}$ 被拉长，SLO 中的首帧指标先崩。</p>\n<p>并发维度上，这套方案的调度开销与块数成正比而非与请求数成正比。重叠区加权融合与运动一致性检查需要 latent 在块间往返搬运并做 CPU/GPU 同步，流式输出节奏被<strong>最慢块</strong>拖住；短块、多块的高并发场景下，同步与调度开销占比过高，GPU 利用率被切碎。跨块 KV 池按重要性淘汰旧块时，若重要性估计只看注意力幅值，会误删承载远距离场景记忆的 KV，长视频后段出现场景漂移——这是超长负载下必须接受的远距离记忆衰减。工程判断很直接：把这类请求路由到分块重叠通道的前提是块帧数稳定、重叠比例可调、KV 池容量与目标时长匹配；对块边界像素级无缝要求极高且不允许任何融合延迟的实时场景，应改走单窗口内一次成型的路径，而不是靠加大重叠比例硬扛。</p>\n<h3 id=\"alg-chunk-overlap-long-video-sec-27\">二十七 · 硬件档位：按单块窗口驻留反推，而不是按时长买卡</h3>\n<p>长视频分块重叠流式生成在部署上的第一条判断不是“总时长多长”，而是“单块窗口能否驻留”。总时长只决定跨块 KV 池要多大，单块窗口才决定算力档位与卡数。显存预算拆成三项：单块 latent 与激活、跨块 KV 池、VAE 解码工作区。前两项随块帧数与重叠帧数变化，第三项随分辨率与解码分块策略变化。工程上先固定分辨率与采样步数，再解一个不等式：单块窗口显存 + 最小可用 KV 池 + VAE 工作区 ≤ 单卡可用显存，解出的最大块帧数就是该档位的容量上限。</p>\n<p>档位划分按这个不等式是否成立来做。单卡能驻留单块窗口时，走单卡单请求或单卡小批；单卡不够但单节点多卡能放下一个块窗口时，走块内张量并行或序列并行，块间仍串行；只有当单块窗口本身跨节点时，才需要把块内并行扩到多节点，此时 NVLink 5 域内的集合通信成本开始进入关键路径。GB200/GB300 NVL72 的价值不在单块算力，而在把块内并行的通信压在同一 NVLink 域内，使块间切换不因跨域通信而拉长节奏。</p>\n<p>代价体现在两个方向。块帧数取大，单块计算效率高、重叠比例相对低，但显存逼近上限，KV 池被压到很小，长视频后段只能靠激进淘汰，远距离一致性丢失。块帧数取小，显存宽松、KV 池大，但每块固定开销（权重加载、内核启动、融合同步）占比上升，流式节奏被短块拖住。一个具体例子：固定分辨率下把块帧数从能驻留的上限往下调一档，单块计算量下降，但块数增加使重叠帧重复计算的总量上升，端到端时长不一定缩短——这正是负载配方里“批大小按重叠帧数与块帧数比值折减”的硬件侧对应。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-28\">二十八 · 并行拓扑：块内并行与块间串行的边界要画清楚</h3>\n<p>这套机制的计算图没有改变，改变的是编排。因此并行拓扑必须区分两层：块内是标准 DiT 的时空注意力，可以按既有方案做张量并行、序列并行或 2-SM MMA 的 tcgen05 路径；块间是严格串行的，因为第 k+1 块要以第 k 块重叠帧的 KV 与 latent 为条件。块间串行意味着块内并行的规模不能无限扩——扩到通信时间超过单块计算时间，块间节奏就被通信主导。</p>\n<p>拓扑选择用一个简单判据：设单块计算时间为 T_chunk，块内并行引入的每块集合通信时间为 T_comm，则有效块周期约为 T_chunk + T_comm + T_fuse，其中 T_fuse 是重叠区融合与运动检查的同步开销。并行度提高使 T_chunk 下降但 T_comm 上升，存在一个使块周期最小的并行度。工程上把块内并行限制在单节点 NVLink 域内，正是为了让 T_comm 保持在可忽略量级；跨节点扩块内并行只在单块窗口确实放不下时才考虑。</p>\n<div class=\"formula\">$$\\text{latency}_{\\text{first chunk}}\\approx T_{\\text{chunk}}+T_{\\text{VAE}},\\qquad \\text{mem}\\propto N_{\\text{overlap}}$$</div>\n<p>首帧时延由第一块的计算加 VAE 解码决定，与后续块数无关，这是流式输出的核心卖点。但块间帧间隔由最慢块决定，而最慢块往往不是计算最重的块，而是融合同步等待最久的块。因此拓扑设计要把融合与运动检查放在与块内计算重叠的流上：第 k 块做 VAE 解码与非重叠帧输出时，第 k+1 块的重叠区融合可以并行准备，避免融合成为串行链上的独立阶段。代价是 latent 在块间往返搬运增加显存带宽占用，在高分辨率下这部分带宽不可忽略。</p>\n<p>具体例子：单节点 8 卡，块内用序列并行把单块窗口切开，块间串行推进。若把并行度从 8 降到 4，单块计算时间上升但通信下降，块周期可能反而缩短；若升到跨节点 16 卡，T_comm 进入关键路径，首帧时延与块间间隔同时变差。这条边界要用实测的块周期曲线来定，而不是按总算力堆卡。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-29\">二十九 · 量化方案：分层给精度，别把融合区当普通激活</h3>\n<p>量化在本机制里的作用不是单纯提速，而是把单块激活与跨块 KV 池同时压小，从而放宽第一节的显存不等式。可用的精度档位是 FP8 与 NVFP4：块内时空注意力的线性层与卷积走低精度，KV 池按块存低精度副本，VAE 解码工作区保持较高精度以免融合后的 latent 被二次量化污染。分层的关键在于重叠区 latent 的数值保真——融合公式对两块 latent 做加权平均，若两块分别被量化到不同舍入误差，融合结果会在边界产生数值台阶，表现为可见的接缝。</p>\n<div class=\"formula\">$$z_t=\\frac{\\sum_{k\\in\\{b-1,b\\}} w_k(t)\\,z_{k,t}}{\\sum_{k} w_k(t)},\\quad w_k(t)=\\exp(-|t-t_k|/\\tau)$$</div>\n<p>因此融合应在较高精度域完成：KV 池里存低精度副本用于条件锚定，重叠帧 latent 在融合前保留一份高精度副本，融合后再决定是否量化回低精度供下一块使用。这条“低精度条件 + 高精度融合”的分工，把量化收益留在计算与 KV 占用上，把数值风险挡在融合环节之外。代价是重叠帧 latent 的高精度副本占用额外显存，其大小正比于 N_overlap，与第一节的 mem ∝ N_overlap 同源；重叠帧越多，这份保真副本越贵。</p>\n<p>KV 池的量化还要考虑淘汰策略的交互。重要性估计若在低精度 KV 上做，注意力幅值的分辨率下降，容易把承载远距离场景记忆的块误判为低重要性。工程做法是重要性估计用一份轻量高精度统计量（如块级注意力熵或块级查询覆盖率）而非逐元素低精度幅值，淘汰决策与存储精度解耦。具体例子：长视频后段出现场景切换时，旧块 KV 的注意力幅值普遍偏低，若只看幅值会整段淘汰，导致切换后的场景漂移；改用块级覆盖率统计可保留少量锚点块，代价是 KV 池有效容量下降，需要按总时长预留冗余。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-30\">三十 · KV 策略：池容量上限就是可支持总时长的硬约束</h3>\n<p>跨块 KV 池是这套机制里唯一随总时长增长的显存项，因此它的容量上限直接决定可支持的总时长。池的增长来自每块新增的非重叠帧 KV，缩减来自重要性淘汰。稳态下池容量由“每块新增量 × 保留块数”决定，保留块数由淘汰阈值控制。工程上把池容量设成硬上限而非软上限，超过即触发淘汰，避免长视频把显存吃穿导致整请求失败。</p>\n<p>淘汰策略的设计要点是区分“运动上下文”与“场景记忆”。重叠帧 KV 承载的是块间运动连续性，属于短期上下文，天然随块推进被新块替代；远距离场景记忆则是稀疏的、跨多块的锚点，需要按块级重要性保留。一个可复现的思路是双层池：近期块 KV 全量保留（覆盖若干块的运动周期），远期块只保留按覆盖率选出的锚点块 KV，锚点数量固定，从而把池容量变成“近期全量 + 固定锚点数”的可预测值。代价是远期锚点稀疏化后，超长视频的远距离一致性只能定性维持，无法做到逐帧精确回溯。</p>\n<p>池容量与块帧数的耦合也要算清：块帧数越大，每块新增 KV 越多，同样池容量下保留块数越少，远期记忆越短。因此第一节里“块帧数取大提效率”与本节“池容量决定总时长”是一对矛盾，配置时要按目标总时长反推块帧数上限。具体例子：目标总时长需要保留 N 个块的远期锚点，每块新增 KV 为 M，则池容量下限约为近期全量块数 × M + N × M；若这个下限加上单块窗口已超显存，就必须降块帧数或降精度，而不是加大淘汰力度——淘汰只能省显存，不能凭空造出记忆。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-31\">三十一 · 调度参数：重叠比例、批大小与流式节奏的三角约束</h3>\n<p>调度层要同时满足三个 SLO：首帧时延、块间帧间隔、端到端时长。首帧时延只受第一块与 VAE 影响，与重叠比例关系不大；块间帧间隔受块周期与融合同步影响；端到端时长受有效吞吐影响。重叠帧占比 r 时有效吞吐约按 1/(1+r) 折减，这是调度参数里最硬的一条约束：r 越大，接缝越少，但吞吐线性下降。r 的取值下限由运动周期所需上下文决定，低于该下限融合后仍会出现接缝与速度突变，且运动一致性检查只能拦截不能修复。</p>\n<p>批大小受单块窗口显存约束而非总时长约束，且要按重叠帧数与块帧数的比值折减。折减的原因是重叠帧在相邻块中被重复计算，批内每个请求的重叠帧都占用一份激活与 KV。工程上把批大小写成可用显存除以“单块窗口 + 单请求 KV 池份额”的下取整，再乘以 1/(1+r) 的吞吐修正来估算有效吞吐，而不是直接把批大小当吞吐线性外推。连续批处理在这里要谨慎：块间串行意味着一个请求的块周期是长尾，批内混入不同块进度的请求会让最慢块拖住整批的融合节奏，因此更稳的做法是按块进度分桶调度，避免跨桶同步。</p>\n<p>融合与运动检查引入 CPU/GPU 同步，是流式节奏的隐藏成本。短块场景下调度开销占比过高，表现为块间帧间隔抖动。可复现的配置思路是把融合做成异步：块生成后立即提交非重叠帧 VAE 解码与流式输出，融合与检查在后台流上对重叠帧做，下一块启动前只等待融合结果的就绪信号而非全同步。代价是 latent 需要双缓冲，显存占用增加一份重叠帧副本，与第三节的高精度融合副本可以合并复用。具体例子：r 取满足运动周期的最小值，批大小按显存下取整后再留一份双缓冲余量，块进度分桶调度，融合异步化——这四条一起构成一个不追求峰值吞吐但节奏稳定的配方。</p>\n<p>最后落在工程判断上：这套机制的部署配方本质是在单块窗口显存、KV 池容量、重叠比例三者之间做约束求解，任何一项拉满都会让另外两项退化。可复现的做法是先按目标总时长定 KV 池下限，再按显存不等式定块帧数上限，再按运动周期定重叠比例下限，最后用块进度分桶与异步融合把调度抖动压住；量化只在这套约束解出之后用来放宽余量，而不是用来掩盖约束冲突。</p>\n<h3 id=\"alg-chunk-overlap-long-video-sec-32\">三十二 · 显存账本：单块窗口、KV 池与 VAE 工作区的三份预算</h3>\n<p>分块重叠流式生成把总时长从显存需求里摘出去，但并没有把显存需求消灭，只是把它拆成了三份互不相同的预算：单块 latent 窗口、跨块 KV 池、VAE 解码工作区。三者性质不同，崩的顺序也不同。单块窗口是硬上限，由固定帧数与分辨率决定，批大小只能在这个窗口内折减，重叠帧占比 $r$ 时每块实际要驻留的帧数是块帧数的 $1+r$ 倍，于是有效批大小按 $1/(1+r)$ 折减——这是重叠比例最直接的显存税。KV 池则是软上限，它随块数单调增长，必须靠重要性淘汰压住，池容量上限直接决定可支持的总时长，而不是由单卡 HBM 容量除以单帧占用算出来的那个乐观值。VAE 工作区最容易被低估：解码只做非重叠新帧，但解码器自身的激活、卷积中间张量与输出帧缓冲在流式节奏下与采样阶段并发存在，尤其在块间衔接点，采样下一块的 latent 与解码上一块的新帧同时占用显存。</p>\n<div class=\"formula\">$$\\text{mem}_{\\text{peak}}\\approx \\underbrace{N_{\\text{chunk}}(1+r)\\,h\\,w\\,c}_{\\text{单块 latent}}+\\underbrace{\\sum_{k\\in\\text{pool}}N_k\\,h\\,w\\,c}_{\\text{跨块 KV}}+\\underbrace{M_{\\text{vae}}}_{\\text{解码工作区}}$$</div>\n<p>工程判断落在峰值而非均值上。以 720p 级分辨率、固定采样步数的长视频请求为例，单块窗口在 FP8 下能驻留，切到 NVFP4 后单块激活与 KV 占用下降，腾出的空间不是拿去加批，而是拿去加 KV 池容量——因为池容量才是总时长的真正瓶颈。反过来，如果把腾出的显存全给批大小，重叠帧的重复计算会让吞吐上升但池很快被挤爆，远距离一致性先丢。这就是“规模上去以后哪里先崩”的第一层答案：先崩的往往不是单块窗口，而是 KV 池被批大小挤占后的淘汰频率。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-33\">三十三 · 带宽：重叠帧的重复搬运比重复计算更贵</h3>\n<p>重叠机制在算力账上表现为重复计算，但在带宽账上表现为重复搬运，而后者常常更早触顶。每块的采样需要把重叠帧的 KV 与 latent 从池中取回作为条件，生成后再把重叠区的 latent 写回待融合，融合时又要两块的重叠 latent 同时在场做加权。这条路径上，HBM 读写量与重叠帧数成正比，与块数成正比，而计算量只与重叠帧的采样步数成正比。当重叠比例 $r$ 提高，计算按 $1+r$ 增长，搬运按 $r$ 增长但基数更大——因为 KV 的每帧字节数远高于 latent 的每帧字节数。跨块 KV 池的读写是纯带宽开销，不产生任何新帧。</p>\n<p>具体到机制上，融合公式 $z_t=\\sum_k w_k(t)z_{k,t}/\\sum_k w_k(t)$，$w_k(t)=\\exp(-|t-t_k|/\\tau)$ 要求第 $b-1$ 块与第 $b$ 块在重叠时刻 $t$ 的 latent 同时驻留，这意味着重叠区在融合窗口内被读两次、写一次。若把融合挪到 CPU 侧做，还要加一次 latent 的 D2H 与 H2D 往返，PCIe 带宽立刻成为节拍器。因此在 Blackwell 节点上更合理的做法是把融合与运动一致性检查压在 GPU 侧的小核里完成，只把检查结果与少量统计量同步回主机，避免 latent 往返。带宽触顶的典型信号是：采样核的 SM 利用率不高但 HBM 吞吐接近饱和，此时加卡无用，减重叠比例或改 KV 池的取回粒度才有效。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-34\">三十四 · 通信：跨块锚定在单节点内是 NVLink 域内的事</h3>\n<p>分块重叠本身不要求多卡，单块窗口能驻留时单卡即可，这是它相对序列并行“用时间换显存”的核心优势。但一旦单块窗口驻留不下、需要单节点多卡切分单块，通信形态就变了：块内注意力切分要走 NVLink 5 域内的集合通信，而跨块 KV 池的取回与融合是点对点的 latent/KV 搬运。这两类通信的代价结构不同——集合通信随切分度上升而放大同步开销，点对点搬运则随重叠帧数线性增长且可以与采样重叠隐藏。</p>\n<p>关键机制是把跨块锚定做成异步预取：在第 $b$ 块采样启动前，把第 $b-1$ 块重叠区的 KV 与 latent 预取到目标卡的显存，与第 $b-1$ 块剩余新帧的解码并行。这样跨块通信落在解码的阴影里，不进入块间关键路径。代价是预取缓冲要额外占显存，且预取时机受最慢块限制——如果第 $b-1$ 块因为运动一致性检查被拖住，预取窗口就被压缩，通信暴露出来。规模上去后通信先崩的场景很具体：块数增多使 KV 池跨卡分布，点对点搬运的跳数与竞争上升，而重叠比例又不能降（降了接缝回来），于是只能在池的分片策略上做文章，把同一场景段的块尽量落在同一卡上，减少跨卡取回。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-35\">三十五 · 功耗与热：流式节奏下的占空比问题</h3>\n<p>长视频流式生成的功耗特征不是峰值算力问题，而是占空比问题。采样阶段是持续高算力、高带宽的密集期，解码与融合阶段是短促的混合期，块间还有同步与调度空隙。重叠比例越高，密集期占比越大，整卡平均功耗越接近密集期功耗，散热设计点被迫上移。更麻烦的是块间同步造成的功耗抖动：GPU 在密集期与空隙之间反复切换，时钟频率随之波动，能效比在抖动中变差。</p>\n<p>机制上的缓解手段是把块间同步做成流水：让第 $b$ 块的采样与第 $b-1$ 块的解码、融合在时间上重叠，用不同硬件单元（Tensor Core 密集采样与 VAE 解码的卷积/访存单元）填满空隙，把占空比拉平。代价是显存峰值上升，因为两块的状态同时在場。这与第一节的显存账本直接冲突——拉平占空比要花显存，而显存又要留给 KV 池。工程判断是：在功耗受限的部署里优先保占空比、牺牲部分池容量并接受更激进的淘汰；在显存受限的部署里反过来，接受功耗抖动换池容量。这个取舍没有中间解，因为两者争的是同一块 HBM。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-36\">三十六 · 尾延迟：最慢块决定流式节奏</h3>\n<p>流式输出的 SLO 由三项组成：首帧时延、块间帧间隔、端到端时长。首帧时延近似为 $T_{\\text{chunk}}+T_{\\text{VAE}}$，其中 $T_{\\text{chunk}}$ 是首块完整采样时间，无法用重叠摊薄，因为首块没有前序锚点。真正决定体验的是块间帧间隔的尾延迟，而它被最慢块拖住：融合与运动一致性检查引入 CPU/GPU 同步，任何一块的检查变慢都会让后续块的输出节奏整体后移，且这种后移不会自动追回，因为块间是串行锚定关系。</p>\n<p>尾延迟的来源有三类，机制上要分开治。其一是重叠不足导致的检查重试——运动一致性检查只能拦截不能修复，拦截后要么降权重融合要么重采样重叠区，后者直接把该块时间翻倍。其二是 KV 池淘汰引发的取回抖动，被淘汰的远距离 KV 若在后续块又被需要，只能重建或降级一致性。其三是短块场景下的调度开销占比过高，融合与检查的固定同步成本摊在很短的块上，单位帧开销被放大。伪代码层面的对策是给块间帧间隔设一个预算上限，超预算的块跳过运动检查的严格模式、改用平滑权重直接融合，把尾延迟压住而把一致性风险显式记账。代价是失败模式从“节奏崩”转成“局部接缝”，这是可接受的交换，因为流式场景里节奏崩是全局可见的，接缝是局部的。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-37\">三十七 · 规模上去以后先崩的顺序</h3>\n<p>把五份代价放在一起，规模扩张时的崩溃顺序是可以排序的。第一步崩的是 KV 池：块数增长使池容量需求线性上升，而淘汰策略若只看注意力幅值，会误删承载远距离场景记忆的 KV，表现为长视频后段场景漂移——这不是显存不够的硬崩，是一致性的软崩，且不可逆，因为被删的 KV 无法从后续块恢复。第二步崩的是带宽：重叠帧的 KV 取回与 latent 融合读写随块数增长，HBM 吞吐先于算力饱和，表现为采样核利用率下降而吞吐不涨。第三步才是单块窗口的显存硬上限，它由固定帧数与分辨率决定，不随总时长变化，反而是最稳定的那一份预算。</p>\n<p>这个顺序给出的工程判断是：扩容时先扩池的淘汰质量而不是池的容量，再扩带宽效率（预取粒度、融合在 GPU 侧完成），最后才考虑切分单块窗口上多卡。因为前两者是随规模恶化的一阶项，后者是常数项。重叠比例 $r$ 的选择也要放在这个顺序里看：提高 $r$ 改善接缝但按 $1/(1+r)$ 折减吞吐、按 $r$ 增加带宽，它同时恶化第二步和第三步，只改善一致性。所以 $r$ 的下限由运动周期所需上下文决定，上限由带宽余量决定，中间没有最优点，只有可行区间——在可行区间内取小值，把余量留给池和预取。规模继续上去时，真正先触顶的永远是那个随块数线性增长、又不产生新帧的开销：跨块 KV 的搬运与淘汰。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-38\">三十八 · 规模上去以后，先崩的是 KV 池而不是单块窗口</h3>\n<p>单块窗口的显存是常数，跨块 KV 池才是随规模线性增长的变量，因此系统扩容时第一个撞墙的几乎总是池容量而非单块 latent。设块数为 $B$、每块保留锚点 KV 为 $K$ 字节、池上限为 $M_{\\text{pool}}$，则可用块数上限为 $\\lfloor M_{\\text{pool}}/K \\rfloor$，超出后必须触发淘汰。淘汰策略若只看注意力幅值，会优先丢掉早期块中幅值低但承载场景记忆的 KV，长视频后段出现场景漂移——这是“能跑完”与“跑得对”之间的分界。工程上应把池预算与单块激活分开核算：显存 = 单块 latent + 池 + VAE 解码工作区，FP8/NVFP4 压缩的是前两项，池的淘汰阈值则决定可支持总时长，二者不可互相挪用。</p>\n<p>吞吐的折减来自重叠帧的重复计算，而非调度。重叠帧占比 $r$ 时，每块实际采样帧数为 $F(1+r)$，有效吞吐约按 $1/(1+r)$ 折减，批大小也须按 $r$ 折减以维持单块窗口驻留。这意味着提高重叠比例换连续性，代价是线性掉吞吐；反过来，$r$ 过低时块边界缺少运动上下文，融合后仍有接缝与速度突变，而运动一致性检查只能拦截不能修复。融合公式 $z_t=\\sum_k w_k(t)z_{k,t}/\\sum_k w_k(t)$、$w_k(t)=\\exp(-|t-t_k|/\\tau)$ 中的 $\\tau$ 与 $r$ 需联合标定：$\\tau$ 过大则边界帧被远块稀释，过小则融合退化为硬切。</p>\n<p>尾延迟与功耗的耦合在流式节奏上暴露得最直接。首块时延近似 $T_{\\text{chunk}}+T_{\\text{VAE}}$，此后块间帧间隔受最慢块支配；重叠区融合与运动检查需要在块间往返搬运 latent 并做 CPU/GPU 同步，短块场景下这部分调度开销占比升高，把本已受限于最慢块的节奏进一步拖长。功耗侧，重叠帧的重复采样与 VAE 反复解码抬高了单位输出帧的能量，长时长请求的能耗随 $r$ 同步上升。因此该方案的规模上限由池显存与淘汰策略共同决定，超长视频必须接受远距离记忆衰减；对块边界像素级无缝且不允许任何融合延迟的实时场景，它并不成立。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先崩的位置</th><th>工程对策</th></tr></thead><tbody><tr><td>总时长增长</td><td>跨块 KV 池容量</td><td>重要性淘汰 + 池预算独立核算</td></tr><tr><td>重叠比例提高</td><td>吞吐按 $1/(1+r)$ 折减</td><td>批大小按 $r$ 折减、$\\tau$ 与 $r$ 联调</td></tr><tr><td>块变短</td><td>融合同步开销占比</td><td>合并检查批次、减少往返搬运</td></tr></tbody></table>\n<h3 id=\"alg-chunk-overlap-long-video-sec-39\">三十九 · 精度问题：融合区的数值塌陷与量化误差放大</h3>\n<p>分块重叠流式生成里，精度故障几乎总是先在重叠区暴露。原因是重叠区要做跨块 latent 加权融合，两个块各自经过扩散/流匹配采样，数值分布并不一致：前一块的重叠帧已经过若干步去噪，后一块的重叠帧作为条件锚点重新进入采样轨迹，两者的 latent 幅值、方差、高频分量都不同。融合公式</p>\n<div class=\"formula\">$$z_t=\\frac{\\sum_{k\\in\\{b-1,b\\}} w_k(t)\\,z_{k,t}}{\\sum_{k} w_k(t)},\\quad w_k(t)=\\exp(-|t-t_k|/\\tau)$$</div>\n<p>在 FP8 或 NVFP4 激活下会把这种分布差异放大：低精度表示下，两块 latent 的尾数截断方向不同，加权和会出现系统性偏置，表现为重叠区亮度台阶或色带。诊断上不要只看整帧 PSNR，要把重叠区单独裁出来算逐帧均值漂移与高频能量比；均值漂移突然抬升而高频能量下降，基本可判定为融合权重与量化尺度不匹配。工程对策是把融合运算强制升到 BF16 或 FP16 执行，只让采样主干走低精度；融合前的 latent 反量化要按块分别做，不能用全局 scale。代价是融合这一步引入一次精度转换与显存往返，单块延迟增加一个小的固定开销，但相比接缝返工可以接受。具体例子：当 $\\tau$ 设得过小、权重在边界帧几乎均分时，两块 latent 的量化噪声等权叠加，重叠区噪声功率约翻倍；把 $\\tau$ 调大让边界帧偏向一侧，噪声被单块主导，视觉上反而更稳。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-40\">四十 · OOM：显存预算的三项分解与淘汰策略的误伤</h3>\n<p>OOM 在本算法里不是总时长问题，而是三项预算同时越界：单块 latent 加跨块 KV 池加 VAE 解码工作区，即 $\\text{mem}\\propto N_{\\text{overlap}}$ 之外还要加上池容量与解码峰值。最常见的 OOM 不是单块窗口撑爆，而是 KV 池随块数单调增长后挤压了 VAE 工作区——流式解码与下一块采样并发时，解码峰值和采样激活叠加。诊断顺序应是：先看单块采样峰值是否稳定（稳定则排除窗口问题），再看 KV 池占用曲线是否随块序号线性上升且淘汰未触发，最后看 VAE 解码与采样的并发窗口是否重叠。淘汰策略的误伤是隐蔽故障：若重要性估计只看注意力幅值，承载远距离场景记忆的 KV 会被判为低权重而删除，显存是降下来了，但长视频后段出现场景漂移。工程判断是给淘汰加一层保护——按块序号保留稀疏锚点 KV（例如每隔若干块留一份），锚点不参与幅值排序。代价是池的有效容量下降，可支持总时长缩短，但换来远距离一致性不崩。例子：一段长镜头里场景主体在画面一侧持续存在，其 KV 注意力幅值在多数帧不高，纯幅值淘汰会先删它，表现为后段主体消失或形变。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-41\">四十一 · 批抖动与路由不均：批大小受窗口约束后的调度失衡</h3>\n<p>本算法的批大小由单块窗口显存决定，而非总时长，因此同一批内不同请求的块帧数、重叠帧数、采样步数一旦不一致，就会出现批内长尾：短块先完成、长块拖住整个批的同步点。批抖动的典型信号是块间帧间隔的方差随批内请求数上升，而单请求单独跑时方差很小。路由不均则出现在多卡或多节点部署：块按请求顺序轮转分配到卡上，若某些卡的 KV 池已接近上限、淘汰更频繁，这些卡上的块会变慢，形成正反馈——越慢越积压，越积压池越满。诊断要看每张卡的块完成时间分布与池占用率的相关性，相关性高即路由不均。对策是按池余量做路由加权，把新块优先派给池占用低的卡；同时对批内请求做块帧数对齐，把重叠比例相近的请求编进同一批。代价是对齐会降低批的填充率，吞吐略降，但尾延迟尖刺被削平。例子：混合长短请求同批时，长请求的重叠帧多、单块计算量大，短请求完成后卡在同步点空转，GPU 利用率曲线呈锯齿状。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-42\">四十二 · 尾延迟尖刺：流式节奏被最慢块拖住</h3>\n<p>流式输出的 SLO 是首帧时延、块间帧间隔、端到端时长三项，其中块间帧间隔的尾部分布最敏感。首块延迟近似 $\\text{latency}_{\\text{first chunk}}\\approx T_{\\text{chunk}}+T_{\\text{VAE}}$，后续块的间隔则由采样、融合、运动一致性检查三段串行决定，而融合与检查需要 latent 在块间往返搬运并做 CPU/GPU 同步，这一段是尖刺的主要来源。诊断方法是把块间间隔拆成三段分别计时，看尖刺落在哪一段：若落在融合段，说明同步等待或搬运带宽受限；若落在检查段，说明运动一致性判据触发返工。工程上应把融合与检查做成异步流水，与下一块的采样重叠执行，只在新帧输出前做一次汇合；检查判据要设宽容阈值，拦截速度突变而非追求逐帧平滑，避免频繁返工。代价是异步流水需要额外的 latent 缓冲，显存预算要预留；返工阈值放宽会放过少量轻微断裂，但换来间隔分布的长尾收敛。例子：短块场景下调度开销占比过高，融合与检查的固定开销摊到很少的新帧上，块间间隔被固定成本主导，此时应合并小块或提高单块帧数来摊薄。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-43\">四十三 · 监控指标与回滚路径</h3>\n<p>监控要围绕可归因的量建面板，而不是只看端到端时长。建议的最小指标集：重叠区逐帧均值漂移与高频能量比（精度）、单块采样峰值与 KV 池占用率及淘汰触发次数（显存）、批内块完成时间方差与每卡池占用相关性（抖动与路由）、块间间隔的三段分解与尾分位（尾延迟）。每个指标都要带块序号维度，因为故障几乎都随时间推进而恶化。回滚路径按故障类型分级：精度类故障先回滚融合精度到 BF16 并调大 $\\tau$，不改采样配置；OOM 类先关并发解码、再收紧池容量、最后才降重叠帧数；抖动与路由类先改路由加权与批对齐，不动模型；尾延迟类先开异步流水，再放宽检查阈值。回滚必须可单请求粒度执行，因为长视频请求之间互不影响，整机回滚会误伤健康请求。工程判断是：重叠帧比例是最后才动的旋钮，因为它直接按 $1/(1+r)$ 折减有效吞吐，动它等于动容量规划。例子：当监控显示淘汰触发次数随块序号单调上升且伴随重叠区漂移抬升，应先加锚点保护而非直接扩池，扩池只是把同一故障推迟到更长时长上发生。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-44\">四十四 · 诊断顺序与工程判据</h3>\n<p>面对一个报障的长视频请求，诊断顺序应是显存→精度→调度→尾延迟，因为 OOM 会伪装成其他故障：池满导致的淘汰会表现为精度漂移，并发解码挤压会表现为块间间隔尖刺。判据上，若单块采样峰值稳定而池占用线性上升，问题在淘汰策略；若池占用稳定而重叠区漂移抬升，问题在融合精度或 $\\tau$；若两者都稳定而块间间隔尾分位抬升，问题在同步与路由。运动一致性检查只能拦截不能修复，因此它触发次数上升本身就是上游重叠不足或 KV 误删的信号，应回查重叠帧数与锚点保护，而不是调检查阈值。最终落在具体机制上：把淘汰的重要性估计从纯注意力幅值改为幅值加块序号锚点保护，并把融合与检查移出关键路径做异步流水，这两项改动同时压住精度漂移与尾延迟尖刺，且不触碰重叠比例这一吞吐旋钮。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-45\">四十五 · 失效边界：从接缝漏检到 KV 误淘汰的连锁反应</h3>\n<p>这套编排的失效不是单点故障，而是沿数据流串联的：重叠帧不足 → 融合后仍有速度突变 → 运动一致性检查只拦截不修复 → 重采样块拖慢整条流。重叠帧数必须覆盖运动周期所需上下文，低于该下限时，$z_t$ 的加权融合只能平滑亮度与纹理，无法恢复块边界处被截断的位移场；此时检查器报出的速度突变是真实缺陷而非噪声，回滚到上一块重采样是唯一修复手段，代价是整块重算加一次 VAE 重解码。诊断上应把重叠区首末帧的光流幅值差、以及融合前后 latent 的 L2 残差作为两个独立指标上报，前者定位运动断裂，后者定位融合是否真的生效——只监控端到端 P99 会把这两类问题混为一谈。</p>\n<p>跨块 KV 池的淘汰是第二个隐蔽失效点。若重要性只按注意力幅值排序，承载远距离场景记忆的低幅值 KV 会被优先删除，表现为后段场景漂移而非报错，监控上只能靠跨块 latent 的全局统计量（如场景嵌入余弦距离）漂移告警来捕捉。池容量上限直接决定可支持总时长，因此容量规划应写成 $\\text{mem}_{\\text{pool}} \\ge N_{\\text{blocks}} \\cdot \\bar{s}_{\\text{KV}} \\cdot (1-\\rho_{\\text{evict}})$，其中 $\\rho_{\\text{evict}}$ 是可接受的淘汰比例；把 $\\rho_{\\text{evict}}$ 当作可调旋钮而非固定值，才能在长视频后段用更多显存换一致性。OOM 通常不来自单块窗口，而来自池增长与 VAE 工作区叠加，故显存预算必须把三者分开计量并各自设硬上限。</p>\n<p>批抖动与尾延迟尖刺来自融合同步。重叠区 latent 需在块间往返搬运并做 CPU/GPU 同步，流式节奏被最慢块拖住；短块场景下调度开销占比过高，表现为块间帧间隔的方差远大于均值。有效吞吐按 $1/(1+r)$ 折减，$r$ 为重叠帧占比，因此批大小须按 $r$ 折减，否则单块窗口显存先于总算力成为瓶颈，出现“批越大越抖”的反常曲线。工程判断是：把融合与检查做成异步流水，允许落后一块的融合结果延迟提交，用一块的缓冲吸收尖刺；回滚策略则以块为粒度——保留上一块的 KV 快照与 latent，检查失败即丢弃当前块并从快照重采样，而不是回退整条流。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>回滚粒度</th></tr></thead><tbody><tr><td>重叠不足、接缝残留</td><td>重叠区光流幅值差突增</td><td>当前块重采样</td></tr><tr><td>KV 误淘汰、场景漂移</td><td>跨块场景嵌入距离漂移</td><td>恢复被淘汰 KV 段</td></tr><tr><td>融合同步、尾延迟尖刺</td><td>块间帧间隔方差</td><td>异步缓冲一块</td></tr></tbody></table>\n<h3 id=\"alg-chunk-overlap-long-video-sec-46\">四十六 · 对照轴：显存换法、连续性来源、延迟结构</h3>\n<p>把长视频分块重叠流式生成放进同族算法谱系，先要确定对照轴。三条轴决定选型：第一条是<strong>显存从哪来</strong>——是用时间切片（重叠帧上下文）把单次注意力窗口压回可驻留范围，还是用多卡序列并行把同一张计算图摊到多个 SM 上，还是用逐帧因果自回归把窗口压到常数。第二条是<strong>连续性由什么保证</strong>——重叠帧 KV/latent 锚定加加权融合、逐帧因果条件、还是纯位置编码外推。第三条是<strong>延迟结构</strong>——首块时延与块间节奏是否解耦，还是整段生成完才出帧。这三条轴不是正交的：选择时间切片就必然引入重叠重复计算，选择序列并行就必然引入跨卡通信，选择逐帧因果就必然放弃块内双向注意力。</p>\n<p>本算法的定位可以一句话概括：不改变单次注意力的计算图，只在推理期做分块编排，用重叠帧的 KV 与 latent 作为跨块条件锚点，块内保留双向注意力。代价是有效吞吐按重叠比例折减，收益是显存需求与总时长解耦。任何选型判断都应回到这个交换：你愿意为多长的视频付多少重复计算。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-47\">四十七 · 决策表：四类候选与适用条件</h3>\n<p>下表把同族候选按工程可判定的条件列出。表中“重叠占比 r”指重叠帧数与块帧数之比，“KV 池上限”指跨块 KV 池可驻留的块数上限。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>候选</th><th>显存来源</th><th>连续性机制</th><th>首帧/块间延迟</th><th>适用条件</th><th>不适用</th></tr>\n</thead>\n<tbody>\n<tr><td>分块重叠流式（本算法）</td><td>单块窗口 + 跨块 KV 池</td><td>重叠帧 KV/latent 锚定 + 时间距离加权融合</td><td>首块 ≈ T_chunk + T_VAE；块间受最慢块拖拽</td><td>总时长远超单次窗口；可接受 r 带来的吞吐折减；允许块间融合同步</td><td>像素级无缝且零融合延迟的实时场景</td></tr>\n<tr><td>序列并行（多卡切同一图）</td><td>多卡分摊激活与 KV</td><td>无跨块概念，全局注意力完整</td><td>受跨卡 all-to-all 通信支配</td><td>单节点 NVLink 域内、总时长仍在全局窗口内、追求无接缝</td><td>总时长超出全局窗口；跨节点带宽不足</td></tr>\n<tr><td>逐帧因果自回归（Rolling Forcing 类）</td><td>常数窗口 + 帧级 KV</td><td>逐帧因果条件，无重叠融合</td><td>帧级流水，首帧快但整段节奏受自回归链长约束</td><td>流式直播式输出；可接受块内单向注意力与误差累积</td><td>需要块内双向一致性的高质量长镜头</td></tr>\n<tr><td>纯位置编码外推</td><td>单次窗口不变</td><td>位置插值/外推</td><td>单次前向延迟</td><td>总时长仅略超窗口</td><td>显著超窗，外推退化明显</td></tr>\n</tbody>\n</table>\n<p>读表的关键是第二列与第四列的耦合：显存来源决定了延迟结构。序列并行把显存压力转成通信压力，块间无融合但有 all-to-all 同步点；逐帧因果把显存压到常数但把连续性押在因果链上，误差随帧数累积；本算法把显存压到单块窗口，代价是 r 的重复计算与融合同步。三者不是优劣关系，是三种不同的资源兑换。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-48\">四十八 · 选型判据：用公式把条件写成不等式</h3>\n<p>把适用条件写成可计算的不等式，选型就从定性变成定量。第一条判据是时长与窗口的关系。设单次注意力窗口可容纳帧数为 $N_{\\text{win}}$，目标总帧数 $N_{\\text{total}}$，块帧数 $N_{\\text{chunk}}$，重叠帧数 $N_{\\text{overlap}}$，则块数</p>\n<div class=\"formula\">$$B=\\left\\lceil \\frac{N_{\\text{total}}-N_{\\text{overlap}}}{N_{\\text{chunk}}-N_{\\text{overlap}}}\\right\\rceil,\\quad r=\\frac{N_{\\text{overlap}}}{N_{\\text{chunk}}-N_{\\text{overlap}}}$$</div>\n<p>当 $N_{\\text{total}}\\le N_{\\text{win}}$ 时，分块重叠没有收益，直接用单次前向或序列并行；只有当 $N_{\\text{total}}&gt;N_{\\text{win}}$ 且 $N_{\\text{chunk}}\\le N_{\\text{win}}$ 时，本算法才成立。第二条判据是吞吐折减：有效吞吐约按 $1/(1+r)$ 折减，因此若 SLO 要求端到端时长 $T_{\\text{e2e}}$，则必须满足</p>\n<div class=\"formula\">$$\\frac{B\\cdot T_{\\text{chunk}}}{1+r}\\le T_{\\text{e2e}},\\quad \\text{mem}_{\\text{KV}}\\propto N_{\\text{pool}}\\ge B_{\\text{resident}}$$</div>\n<p>这两个不等式一起把 r 与 KV 池上限钉死：r 太小接缝拦不住，r 太大吞吐不达标；池上限太小远距离记忆被淘汰，太大则单卡显存不够。工程上先由画质要求定 $N_{\\text{overlap}}$ 下限（不少于运动周期所需上下文），再由 SLO 反推 $N_{\\text{chunk}}$ 上限，最后用池上限校验总时长可行性。</p>\n<p>具体例子：一条需要跨多个场景切换的长视频，若场景切换处运动周期长，重叠帧数必须覆盖切换前后的运动上下文，否则融合后速度突变。此时若 SLO 又要求块间帧间隔稳定，就必须把块帧数调大以摊薄融合同步开销，代价是单块显存上升——这正是本算法与序列并行的分界：当单块窗口已逼近单卡显存上限而总时长仍不够时，序列并行用多卡换显存开始变得必要。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-49\">四十九 · 与量化、稀疏、缓存的组合次序</h3>\n<p>选型不只发生在算法之间，也发生在同一请求内的技术叠加次序。本算法的重叠帧重复计算会放大任何单块内的算子代价，因此量化与稀疏的收益被 r 直接稀释：若单块内用 NVFP4/FP8 把激活与 KV 占用降下来，收益是单块窗口能容纳更多帧，从而降低 r 或提高 $N_{\\text{chunk}}$，这是间接收益而非直接吞吐收益。组合次序应为：先定量化精度档位决定单块显存预算，再定 $N_{\\text{chunk}}$ 与 $N_{\\text{overlap}}$，最后定 KV 池淘汰策略。反过来先定分块参数再套量化，往往得到无法驻留的配置。</p>\n<p>与轨迹感知缓存复用的关系是竞争同一份计算预算：缓存复用减少单块采样步数，重叠重复计算增加块数，两者都作用在 $T_{\\text{chunk}}$ 上。若缓存命中率高，$T_{\\text{chunk}}$ 下降，块间节奏变快，融合同步的相对开销上升，此时应减少重叠搬运的同步点而不是继续加缓存。与动态稀疏时空注意力的关系则是：稀疏降低单块注意力代价，但不改变跨块锚定需求，稀疏后的块边界接缝问题依旧存在，重叠融合不能省。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-50\">五十 · 失败模式对应的选型纠偏</h3>\n<p>三类失败模式各自指向一个选型纠偏动作。第一类，重叠比例过低导致接缝与速度突变：这不是调参问题而是选型问题——说明当前 $N_{\\text{overlap}}$ 不满足运动周期下限，应提高 r 或改用块内双向注意力更强的序列并行方案；运动一致性检查只能拦截不能修复，拦截率上升本身就是选型信号。第二类，KV 池淘汰过早导致远距离场景漂移：说明池上限与总时长不匹配，若重要性估计只看注意力幅值会误删承载远距离记忆的 KV，纠偏方向是提高池上限或改用分层淘汰（场景级锚点常驻、帧级 KV 淘汰），代价是显存预算上升。第三类，融合与检查的 CPU/GPU 同步拖住流式节奏：说明块太短、调度开销占比过高，纠偏方向是增大 $N_{\\text{chunk}}$ 摊薄同步，或把融合搬到 GPU 侧以流水方式与下一块采样重叠。</p>\n<p>这三类纠偏共同指向一个判断：本算法的参数不是独立可调的，r、$N_{\\text{chunk}}$、池上限三者由画质、SLO、显存三条约束联立决定，任何单参数调优都会把失败模式从一个转移到另一个。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-51\">五十一 · 选型的工程落点</h3>\n<p>最终判断落在一条可执行的决策链上：先测 $N_{\\text{win}}$ 与单卡显存可驻留的 $N_{\\text{chunk}}$，若 $N_{\\text{total}}\\le N_{\\text{win}}$ 直接单次前向；否则按运动周期定 $N_{\\text{overlap}}$ 下限，按 SLO 与 $1/(1+r)$ 折减定 $N_{\\text{chunk}}$ 上限，两者冲突时优先保画质则接受吞吐折减、优先保 SLO 则引入序列并行分摊单块显存；最后用 $B_{\\text{resident}}\\le N_{\\text{pool}}$ 校验总时长，不满足则接受远距离记忆衰减或升级硬件档位。这条链上每一步都有明确的失败信号：接缝拦截率、场景漂移检测、块间帧间隔抖动，三者分别对应 r 不足、池不足、块太短。选型不是一次决定，而是把这三个信号接进运行时监控，让参数随负载漂移而调整——这才是分块重叠流式生成在 Blackwell 上稳定跑长视频的工程落点。</p>\n\n<h3 id=\"alg-chunk-overlap-long-video-sec-52\">五十二 · 选型边界：重叠分块、自回归滚动与序列并行怎么分工</h3>\n<p>把分块重叠流式生成放进同族算法谱系里，它的定位是<strong>推理期的分块编排</strong>：不改单次注意力的计算图，靠重叠帧的 KV/latent 做跨块条件锚定。因此它与两条相邻路线构成三角选择：纯自回归 Rolling Forcing 类方法（paper-rolling-forcing-autoregressive-long-2025）以逐帧因果生成换取无界时长，块内只有单向注意力，连续性由因果链本身保证，代价是每帧都要一次前向、并行度低、首帧之后逐帧抖动；序列并行（含上下文并行）则是用多卡换显存，单次注意力窗口被切到多卡上，块内仍是全局双向注意力，代价是每步都要跨卡 all-gather/reduce-scatter，通信量随序列长度线性增长，在 NVLink 5 域内尚可、跨节点即迅速劣化；本方案用时间换显存，单卡或单节点即可驻留单块窗口，块内保留双向注意力，连续性靠重叠融合而非因果约束。三者不是替代关系：序列并行解决“单块窗口本身放不下”，本方案解决“总时长远超窗口”，自回归解决“根本不想设窗口上限”。</p>\n<p>决策表按四个判据排序，先看显存与拓扑，再看连续性要求与延迟预算：</p>\n<table class=\"mini\"><thead><tr><th>判据</th><th>重叠分块流式</th><th>自回归滚动</th><th>序列并行</th></tr></thead><tbody><tr><td>单块窗口能否驻留</td><td>必须能，否则先降分辨率/量化</td><td>能，窗口更小</td><td>不能时才需要</td></tr><tr><td>总时长与窗口之比</td><td>任意倍数，受 KV 池上限约束</td><td>无上限</td><td>受卡数与通信预算约束</td></tr><tr><td>块边界连续性</td><td>重叠锚定+加权融合，需重叠帧足够</td><td>因果链天然连续，无接缝概念</td><td>无边界，但通信同步点多</td></tr><tr><td>首帧/块间延迟</td><td>首块 $T_{\\text{chunk}}+T_{\\text{VAE}}$，块间受最慢块拖累</td><td>首帧快，后续逐帧稳定但吞吐低</td><td>每步通信抬高峰值延迟</td></tr></tbody></table>\n<p>本方案的失效条件集中在三处。其一是重叠比例 $r$ 过低：块边界缺少足够运动上下文，融合只能平滑不能生成，运动一致性检查只能拦截速度突变而不能修复，接缝依旧存在；重叠帧数应按运动周期而非固定比例设定，快速运动场景需要更大 $r$。其二是跨块 KV 池的淘汰策略：若重要性只看注意力幅值，承载远距离场景记忆的低幅值 KV 会被误删，表现为长视频后段场景漂移，这类损失不可逆，因为被淘汰的 KV 无法从后续块重建。其三是同步开销：融合权重与运动检查要求 latent 在块间往返搬运并做 CPU/GPU 同步，短块场景下调度开销占比过高，流式节奏被最慢块拖住。系统代价可用一条折减关系概括：有效吞吐约按 $1/(1+r)$ 衰减，显存则满足</p>\n<div class=\"formula\">$$\\text{mem}\\approx M_{\\text{chunk}}(1+r)+M_{\\text{KVpool}}(N_{\\text{blocks}})+M_{\\text{VAE}},\\quad N_{\\text{blocks}}=\\left\\lceil \\frac{N_{\\text{total}}-N_{\\text{overlap}}}{N_{\\text{chunk}}-N_{\\text{overlap}}}\\right\\rceil$$</div>\n<p>其中 $M_{\\text{KVpool}}$ 随块数增长，池容量上限直接决定可支持的总时长——这是本方案真正的规模天花板，而不是单块窗口。工程判断上：若请求是长时长、固定分辨率、固定采样步数且允许块间存在融合延迟，选本方案，批大小按 $N_{\\text{overlap}}/N_{\\text{chunk}}$ 折减而非按总时长折减，量化用 FP8/NVFP4 压单块激活与 KV 占用；若要求块边界像素级无缝且不接受任何融合延迟的实时场景，本方案不适用，应转向因果自回归；若单块窗口本身已放不下，先用序列并行把窗口摊到多卡，再在其上叠分块。两条机制线的论文锚点为 paper-histream-efficient-high-resolution-v-2025（高分辨率流式分块重叠）与 paper-rolling-forcing-autoregressive-long-2025（自回归长视频），选型时应把它们视为互补的两端而非竞争方案。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2025 · 视频 VAE 与时空 token 压缩</td></tr><tr><td>解决什么</td><td>长视频超出单次DiT的时空注意力窗口与显存上限，直接切块会在块边界产生接缝与运动断裂；流式输出还要求块间低延迟衔接。</td></tr><tr><td>一句话机制</td><td>把长视频切成带重叠帧的块，块间用重叠帧的KV/ latent做锚定与运动对齐，生成完一块立即VAE解码流式输出，重叠区…</td></tr><tr><td>代价与失效</td><td>重叠帧带来重复计算，重叠比例越高吞吐越低；块间KV池仍随块数增长需淘汰策略。；加权融合与运动检查增加CPU/GPU同步，流式输出节奏受最慢…</td></tr><tr><td>后继</td><td>少步蒸馏采样</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-chunk-overlap-long-video · 共 8 个片段</p>\n";break;}}})();
